window.CLASSDB={"barbare":{"tab":[{"pb":2,"f":["Rage","Défense sans armure"],"x":[["Rages",2],["Dégâts de rage","+2"]]},{"pb":2,"f":["Témérité","Sens du danger"],"x":[["Rages",2],["Dégâts de rage","+2"]]},{"pb":2,"f":["Voie primitive"],"x":[["Rages",3],["Dégâts de rage","+2"]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Rages",3],["Dégâts de rage","+2"]]},{"pb":3,"f":["Attaque supplémentaire","Déplacement rapide"],"x":[["Rages",3],["Dégâts de rage","+2"]]},{"pb":3,"f":["Aptitude de voie"],"x":[["Rages",4],["Dégâts de rage","+2"]]},{"pb":3,"f":["Instinct sauvage"],"x":[["Rages",4],["Dégâts de rage","+2"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Rages",4],["Dégâts de rage","+2"]]},{"pb":4,"f":["Critique brutal (1 dé)"],"x":[["Rages",4],["Dégâts de rage","+3"],["Critique brutal","+1 dé"]]},{"pb":4,"f":["Aptitude de voie"],"x":[["Rages",4],["Dégâts de rage","+3"],["Critique brutal","+1 dé"]]},{"pb":4,"f":["Rage implacable"],"x":[["Rages",4],["Dégâts de rage","+3"],["Critique brutal","+1 dé"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Rages",5],["Dégâts de rage","+3"],["Critique brutal","+1 dé"]]},{"pb":5,"f":["Critique brutal (2 dés)"],"x":[["Rages",5],["Dégâts de rage","+3"],["Critique brutal","+2 dé"]]},{"pb":5,"f":["Aptitude de voie"],"x":[["Rages",5],["Dégâts de rage","+3"],["Critique brutal","+2 dé"]]},{"pb":5,"f":["Rage persistante"],"x":[["Rages",5],["Dégâts de rage","+3"],["Critique brutal","+2 dé"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Rages",5],["Dégâts de rage","+4"],["Critique brutal","+2 dé"]]},{"pb":6,"f":["Critique brutal (3 dés)"],"x":[["Rages",6],["Dégâts de rage","+4"],["Critique brutal","+3 dé"]]},{"pb":6,"f":["Puissance indomptable"],"x":[["Rages",6],["Dégâts de rage","+4"],["Critique brutal","+3 dé"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Rages",6],["Dégâts de rage","+4"],["Critique brutal","+3 dé"]]},{"pb":6,"f":["Champion primitif"],"x":[["Rages","illimitées"],["Dégâts de rage","+4"],["Critique brutal","+3 dé"]]}],"feats":{"Rage":"Au combat, vous êtes animé par une férocité bestiale. À votre tour, vous pouvez entrer en rage par une action bonus.\nSous l’effet de la rage et à la condition de ne pas porter d’armure lourde, vous recevez les bénéfices suivants :\n- Vous êtes avantagé aux tests de Force et aux jets de sauvegarde de Force.\n- Quand vous effectuez une attaque d’arme de corps à corps basée sur la Force, vous bénéficiez d’un bonus au jet de dégâts qui augmente avec votre niveau de barbare, comme indiqué à la colonne « Dégâts de rage » de la table « Le barbare ».\n- Vous bénéficiez de la résistance aux dégâts contondants, perforants et tranchants.\nSi vous êtes capable de lancer des sorts, vous ne pouvez pas en lancer ni rester concentré sur un sort tant que vous êtes en rage.\nVotre rage dure 1 minute. Elle prend fin prématurément si vous subissez l’état inconscient ou si votre tour se termine sans que vous ayez attaqué une créature hostile ni subi de dégâts depuis votre tour précédent. À votre tour, vous pouvez en outre mettre fin à votre rage par une action bonus.\nUne fois que vous êtes entré en rage autant de fois qu’indiqué pour votre niveau de barbare à la colonne « Rages » de la table « Le barbare », vous devez terminer un repos long avant de pouvoir à nouveau entrer en rage.","Défense sans armure":"Tant que vous ne portez pas d’armure, votre classe d’armure est égale à 10 + votre modificateur de Dextérité + votre modificateur de Constitution. Vous conservez ce bénéfice si vous vous servez d’un bouclier.","Témérité":"À partir du niveau 2, vous pouvez renoncer à toute velléité de vous défendre au profit d’une attaque à outrance. Lors de votre tour, quand vous effectuez votre première attaque, vous pouvez décider d’attaquer avec témérité. Vous êtes alors avantagé aux jets d’attaque d’arme de corps à corps basés sur la Force pendant ce tour, mais les jets d’attaque effectués contre vous sont avantagés jusqu’à votre tour suivant.","Sens du danger":"En atteignant le niveau 2, vous acquérez un don surnaturel qui vous permet d’esquiver plus aisément les dangers qu’un autre que vous remarquerait trop tard.\nVous avez l’avantage à vos jets de sauvegarde de Dextérité contre tout effet que vous voyez, comme les pièges et certains sorts. Pour pouvoir bénéficier de cette aptitude, vous ne devez pas être aveuglé, assourdi ou neutralisé.","Voie primitive":"Au niveau 3, vous choisissez une voie qui va façonner la façon dont s’exprime votre rage. La voie du berserker est proposée ici, détaillée à la fin de la section consacrée à cette classe. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6, 10 et 14.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Attaque supplémentaire":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.","Déplacement rapide":"À partir du niveau 5, votre vitesse augmente de 3 m tant que vous ne portez pas d’armure lourde.","Aptitude de voie":"Au niveau 3, vous choisissez une voie qui va façonner la façon dont s’exprime votre rage. La voie du berserker est proposée ici, détaillée à la fin de la section consacrée à cette classe. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6, 10 et 14.","Instinct sauvage":"À compter du niveau 7, votre instinct s’est affûté au point que vous êtes avantagé aux jets d’initiative.\nEn outre, si vous êtes surpris au début du combat et n’êtes pas neutralisé, vous pouvez agir normalement lors de votre premier tour, mais uniquement si vous entrez en rage avant toute chose lors de ce tour.","Critique brutal (1 dé)":"À partir du niveau 9, vous pouvez lancer un dé de dégâts d’arme supplémentaire pour déterminer les dégâts supplémentaires causés par le coup critique d’une attaque de corps à corps.\nCe bonus passe à deux dés supplémentaires au niveau 13, puis à trois dés supplémentaires au niveau 17.","Rage implacable":"À partir du niveau 11, votre rage vous permet de continuer à combattre même en étant grièvement blessé. Si vous tombez à 0 point de vie alors que vous êtes en rage, et que vous ne mourez pas sur le coup, vous pouvez effectuer un jet de sauvegarde de Constitution DD 10. En cas de réussite, vous conservez 1 point de vie.\nPar la suite et chaque fois que vous réutilisez cette aptitude, le DD augmente de 5. Lorsque vous terminez un repos court ou long, le DD retombe à 10.","Critique brutal (2 dés)":"À partir du niveau 9, vous pouvez lancer un dé de dégâts d’arme supplémentaire pour déterminer les dégâts supplémentaires causés par le coup critique d’une attaque de corps à corps.\nCe bonus passe à deux dés supplémentaires au niveau 13, puis à trois dés supplémentaires au niveau 17.","Rage persistante":"À partir du niveau 15, la rage qui vous habite est si féroce qu’elle ne se termine que si vous subissez l’état inconscient ou décidez d’y mettre fin.","Critique brutal (3 dés)":"À partir du niveau 9, vous pouvez lancer un dé de dégâts d’arme supplémentaire pour déterminer les dégâts supplémentaires causés par le coup critique d’une attaque de corps à corps.\nCe bonus passe à deux dés supplémentaires au niveau 13, puis à trois dés supplémentaires au niveau 17.","Puissance indomptable":"À partir du niveau 18, si le total obtenu lors d’un test de Force est inférieur à votre valeur de Force, vous pouvez utiliser celle-ci à la place du total obtenu.","Champion primitif":"Au niveau 20, vous devenez l’incarnation de la puissance du monde sauvage. Vos valeurs de Force et de Constitution augmentent de 4. Votre maximum pour ces deux valeurs est désormais de 24."},"subs":{"Voie du berserker":[[3,"Frénésie","À partir du moment où vous choisissez cette voie au niveau 3, vous pouvez entrer en frénésie lors de vos rages. Ce faisant, pendant toute la durée de la rage, vous pouvez effectuer une unique attaque d’arme de corps à corps par une action bonus à chacun de vos tours suivants. Lorsque votre rage prend fin, vous subissez un niveau d’épuisement (comme décrit en annexe MdJ-A)."],[6,"Rage aveugle","À partir du niveau 6, vous ne pouvez plus être ni charmé ni effrayé quand vous êtes en rage. Si vous étiez charmé ou effrayé au moment d’entrer en rage, l’effet est suspendu pendant toute la durée de la rage."],[10,"Présence intimidante","À partir du niveau 10, vous pouvez consacrer votre action à effrayer quelqu’un grâce à votre présence intimidante. Ce faisant, choisissez une créature que vous voyez dans un rayon de 9 m. Si cette créature vous voit ou vous entend, elle doit réussir un jet de sauvegarde de Sagesse (DD égal à 8 + votre bonus de maîtrise + votre modificateur de Charisme) sous peine d’être effrayée par vous jusqu’à la fin de votre tour suivant. Lors des tours qui suivent, vous pouvez consacrer votre action à prolonger la durée de cet effet sur la créature effrayée jusqu’à la fin de votre tour suivant. Cet effet prend fin si la créature termine son tour sans vous avoir en champ de vision ou en étant à plus de 18 m de vous.\nSi cette créature réussit son jet de sauvegarde, vous ne pouvez plus utiliser cette aptitude sur elle pendant 24 heures."],[14,"Représailles","À partir du niveau 14, quand vous subissez des dégâts d’une créature située dans un rayon de 1,50 m de vous, vous pouvez jouer votre réaction pour effectuer une attaque d’arme de corps à corps contre cette créature."]],"Voie du guerrier totem":[[3,"Quêteur spirituel","Tu peux lancer Communication avec les animaux et Sens animal, uniquement en rituel."],[3,"Esprit totem","En rage, selon ton totem : aigle (désavantage aux attaques d'opportunité contre toi, Foncer en action bonus), loup (tes alliés ont l'avantage contre les ennemis à 1,5 m de toi), ours (résistance à tous les dégâts sauf psychiques)."],[6,"Aspect de la bête","Aigle : tu vois très loin sans gêne dans la pénombre. Loup : pistage et discrétion en voyage. Ours : capacité de charge doublée, avantage pour soulever, pousser ou briser."],[10,"Marcheur spirituel","Tu peux lancer Communion avec la nature en rituel ; un esprit animal te répond."],[14,"Lien totémique","En rage : aigle (vol sur de courtes distances), loup (après une attaque au contact, action bonus pour mettre une grande créature ou plus petite à terre), ours (les ennemis à 1,5 m ont un désavantage pour attaquer tes alliés)."]],"Voie de la magie sauvage":[[3,"Sens de la magie","Par une action, tu perçois sorts et objets magiques à 18 m. Utilisations = bonus de maîtrise par repos long."],[3,"Sursaut sauvage","Quand tu entres en rage, lance 1d8 sur la table de magie sauvage : un effet magique aléatoire t'accompagne."],[6,"Réserve de magie","Par une action, une créature ajoute 1d3 à ses jets pendant 10 minutes, ou récupère un emplacement de sort (une fois par repos long)."],[10,"Réaction instable","En rage, après avoir subi des dégâts ou raté une sauvegarde, réaction pour relancer le sursaut sauvage."],[14,"Sursaut contrôlé","Pour un sursaut sauvage, lance deux dés et choisis l'effet (n'importe lequel sur un double)."]]}},"barde":{"tab":[{"pb":2,"f":["Sorts : Barde","Inspiration bardique (d6)"],"x":[["Inspiration bardique","d6"]]},{"pb":2,"f":["Touche-à-tout","Chant reposant (d6)"],"x":[["Inspiration bardique","d6"],["Chant reposant","d6"]]},{"pb":2,"f":["Expertise","Collège bardique"],"x":[["Inspiration bardique","d6"],["Chant reposant","d6"]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Inspiration bardique","d6"],["Chant reposant","d6"]]},{"pb":3,"f":["Inspiration bardique (d8)","Source d’inspiration"],"x":[["Inspiration bardique","d8"],["Chant reposant","d6"]]},{"pb":3,"f":["Contre-charme","Aptitude de Collège bardique"],"x":[["Inspiration bardique","d8"],["Chant reposant","d6"]]},{"pb":3,"f":[],"x":[["Inspiration bardique","d8"],["Chant reposant","d6"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Inspiration bardique","d8"],["Chant reposant","d6"]]},{"pb":4,"f":["Chant reposant (d8)"],"x":[["Inspiration bardique","d8"],["Chant reposant","d8"]]},{"pb":4,"f":["Expertise","Inspiration bardique (d10)","Secrets magiques"],"x":[["Inspiration bardique","d10"],["Chant reposant","d8"]]},{"pb":4,"f":[],"x":[["Inspiration bardique","d10"],["Chant reposant","d8"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Inspiration bardique","d10"],["Chant reposant","d8"]]},{"pb":5,"f":["Chant reposant (d10)"],"x":[["Inspiration bardique","d10"],["Chant reposant","d10"]]},{"pb":5,"f":["Magical Secrets","Aptitude de Collège bardique"],"x":[["Inspiration bardique","d10"],["Chant reposant","d10"]]},{"pb":5,"f":["Inspiration bardique (d12)"],"x":[["Inspiration bardique","d12"],["Chant reposant","d10"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Inspiration bardique","d12"],["Chant reposant","d10"]]},{"pb":6,"f":["Chant reposant (d12)"],"x":[["Inspiration bardique","d12"],["Chant reposant","d12"]]},{"pb":6,"f":["Magical Secrets"],"x":[["Inspiration bardique","d12"],["Chant reposant","d12"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Inspiration bardique","d12"],["Chant reposant","d12"]]},{"pb":6,"f":["Inspiration supérieure"],"x":[["Inspiration bardique","d12"],["Chant reposant","d12"]]}],"feats":{"Sorts : Barde":"Vous avez appris à détisser et remodeler la trame de la réalité en harmonie avec vos désirs et vos mélodies. Vos sorts s’ajoutent à votre vaste répertoire : une magie que vous pouvez accorder à la situation.","Inspiration bardique (d6)":"Vous savez galvaniser autrui par la parole ou la musique. Pour ce faire, par une action bonus à votre tour vous désignez une créature autre que vous dans un rayon de 18 m. Si la créature vous entend, elle reçoit un dé d’Inspiration bardique (d6).\nDans les 10 prochaines minutes, la créature peut lancer le dé pour en ajouter le résultat à un test de caractéristique, un jet d’attaque ou un jet de sauvegarde qu’elle effectue. La créature peut attendre d’avoir lancé le d20 avant de décider d’utiliser le dé d’Inspiration bardique, à condition de ne pas attendre sciemment que le MJ annonce la réussite ou l’échec du jet. Une fois le dé d’Inspiration bardique lancé, il est perdu. Une même créature ne peut pas disposer de plus d’un dé d’Inspiration bardique à la fois.\nVous pouvez recourir à cette aptitude autant de fois que votre modificateur de Charisme (minimum une fois). Vous récupérez ce quota en terminant un repos long.\nVotre dé d’Inspiration bardique évolue lorsque vous atteignez certains niveaux dans cette classe. Ce dé devient un d8 au niveau 5, un d10 au niveau 10 et un d12 au niveau 15.","Touche-à-tout":"À partir du niveau 2, vous pouvez ajouter la moitié de votre bonus de maîtrise (arrondi à l’inférieur) à tous vos tests de caractéristique auxquels vous n’appliquez pas déjà votre bonus de maîtrise.","Chant reposant (d6)":"À partir du niveau 2, vos mélodies apaisantes ou votre éloquence peuvent redonner vigueur à vos alliés blessés dans le cadre d’un repos court. Si vous ou toute créature amicale qui entend votre interprétation récupérez des points de vie en dépensant un ou plusieurs DV à la fin du repos court, chacune des créatures concernées récupère 1d6 points de vie supplémentaires.\nLa quantité de points de vie supplémentaires augmente quand vous atteignez certains niveaux dans cette classe : le dé passe à 1d8 au niveau 9, 1d10 au niveau 13 et 1d12 au niveau 17.","Expertise":"Au niveau 3, choisissez deux de vos maîtrises de compétence. Votre bonus de maîtrise est doublé pour tous vos tests de caractéristique associés à l’une ou l’autre des maîtrises choisies.\nAu niveau 10, cette aptitude bénéficie à deux maîtrises de compétence supplémentaires.","Collège bardique":"Au niveau 3, vous puisez dans les techniques avancées du collège bardique de votre choix, comme le Collège du Savoir. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6 et 14.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Inspiration bardique (d8)":"Vous savez galvaniser autrui par la parole ou la musique. Pour ce faire, par une action bonus à votre tour vous désignez une créature autre que vous dans un rayon de 18 m. Si la créature vous entend, elle reçoit un dé d’Inspiration bardique (d6).\nDans les 10 prochaines minutes, la créature peut lancer le dé pour en ajouter le résultat à un test de caractéristique, un jet d’attaque ou un jet de sauvegarde qu’elle effectue. La créature peut attendre d’avoir lancé le d20 avant de décider d’utiliser le dé d’Inspiration bardique, à condition de ne pas attendre sciemment que le MJ annonce la réussite ou l’échec du jet. Une fois le dé d’Inspiration bardique lancé, il est perdu. Une même créature ne peut pas disposer de plus d’un dé d’Inspiration bardique à la fois.\nVous pouvez recourir à cette aptitude autant de fois que votre modificateur de Charisme (minimum une fois). Vous récupérez ce quota en terminant un repos long.\nVotre dé d’Inspiration bardique évolue lorsque vous atteignez certains niveaux dans cette classe. Ce dé devient un d8 au niveau 5, un d10 au niveau 10 et un d12 au niveau 15.","Source d’inspiration":"À partir du niveau 5, vous récupérez votre quota d’Inspiration bardique lorsque vous terminez un repos court ou long.","Contre-charme":"Au niveau 6, vous acquérez la capacité de perturber les effets mentaux par le biais de notes de musique ou de paroles de pouvoir. Au prix d’une action, vous pouvez entamer une représentation qui dure jusqu’à la fin de votre tour suivant. Durant cet intervalle, vous et toutes les créatures amicales dans un rayon de 9 m de vous êtes avantagés aux jets de sauvegarde contre les états effrayé et charmé. Une créature ne peut profiter de ce bénéfice que si elle vous entend. Votre représentation prend fin prématurément si vous êtes neutralisé ou réduit au silence, ou si vous y mettez volontairement un terme (aucune action requise).","Aptitude de Collège bardique":"Au niveau 3, vous puisez dans les techniques avancées du collège bardique de votre choix, comme le Collège du Savoir. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6 et 14.","Chant reposant (d8)":"À partir du niveau 2, vos mélodies apaisantes ou votre éloquence peuvent redonner vigueur à vos alliés blessés dans le cadre d’un repos court. Si vous ou toute créature amicale qui entend votre interprétation récupérez des points de vie en dépensant un ou plusieurs DV à la fin du repos court, chacune des créatures concernées récupère 1d6 points de vie supplémentaires.\nLa quantité de points de vie supplémentaires augmente quand vous atteignez certains niveaux dans cette classe : le dé passe à 1d8 au niveau 9, 1d10 au niveau 13 et 1d12 au niveau 17.","Inspiration bardique (d10)":"Vous savez galvaniser autrui par la parole ou la musique. Pour ce faire, par une action bonus à votre tour vous désignez une créature autre que vous dans un rayon de 18 m. Si la créature vous entend, elle reçoit un dé d’Inspiration bardique (d6).\nDans les 10 prochaines minutes, la créature peut lancer le dé pour en ajouter le résultat à un test de caractéristique, un jet d’attaque ou un jet de sauvegarde qu’elle effectue. La créature peut attendre d’avoir lancé le d20 avant de décider d’utiliser le dé d’Inspiration bardique, à condition de ne pas attendre sciemment que le MJ annonce la réussite ou l’échec du jet. Une fois le dé d’Inspiration bardique lancé, il est perdu. Une même créature ne peut pas disposer de plus d’un dé d’Inspiration bardique à la fois.\nVous pouvez recourir à cette aptitude autant de fois que votre modificateur de Charisme (minimum une fois). Vous récupérez ce quota en terminant un repos long.\nVotre dé d’Inspiration bardique évolue lorsque vous atteignez certains niveaux dans cette classe. Ce dé devient un d8 au niveau 5, un d10 au niveau 10 et un d12 au niveau 15.","Secrets magiques":"Au niveau 10, vous avez pioché du savoir magique dans un vaste éventail de disciplines. Choisissez deux sorts de n’importe quelle classe, y compris celle de barde. Chaque sort choisi doit être d’un niveau que vous pouvez lancer comme indiqué sur la table « Le barde » ou un sort mineur.\nLes sorts choisis sont considérés dans votre cas comme des sorts de barde, mais ne sont pas décomptés de vos sorts connus comme indiqué dans la colonne « Sorts connus » de la table « Le barde ».\nVous apprenez deux sorts supplémentaires de n’importe quelle classe au niveau 14 et deux autres au niveau 18.","Chant reposant (d10)":"À partir du niveau 2, vos mélodies apaisantes ou votre éloquence peuvent redonner vigueur à vos alliés blessés dans le cadre d’un repos court. Si vous ou toute créature amicale qui entend votre interprétation récupérez des points de vie en dépensant un ou plusieurs DV à la fin du repos court, chacune des créatures concernées récupère 1d6 points de vie supplémentaires.\nLa quantité de points de vie supplémentaires augmente quand vous atteignez certains niveaux dans cette classe : le dé passe à 1d8 au niveau 9, 1d10 au niveau 13 et 1d12 au niveau 17.","Magical Secrets":"Au niveau 10, vous avez pioché du savoir magique dans un vaste éventail de disciplines. Choisissez deux sorts de n’importe quelle classe, y compris celle de barde. Chaque sort choisi doit être d’un niveau que vous pouvez lancer comme indiqué sur la table « Le barde » ou un sort mineur.\nLes sorts choisis sont considérés dans votre cas comme des sorts de barde, mais ne sont pas décomptés de vos sorts connus comme indiqué dans la colonne « Sorts connus » de la table « Le barde ».\nVous apprenez deux sorts supplémentaires de n’importe quelle classe au niveau 14 et deux autres au niveau 18.","Inspiration bardique (d12)":"Vous savez galvaniser autrui par la parole ou la musique. Pour ce faire, par une action bonus à votre tour vous désignez une créature autre que vous dans un rayon de 18 m. Si la créature vous entend, elle reçoit un dé d’Inspiration bardique (d6).\nDans les 10 prochaines minutes, la créature peut lancer le dé pour en ajouter le résultat à un test de caractéristique, un jet d’attaque ou un jet de sauvegarde qu’elle effectue. La créature peut attendre d’avoir lancé le d20 avant de décider d’utiliser le dé d’Inspiration bardique, à condition de ne pas attendre sciemment que le MJ annonce la réussite ou l’échec du jet. Une fois le dé d’Inspiration bardique lancé, il est perdu. Une même créature ne peut pas disposer de plus d’un dé d’Inspiration bardique à la fois.\nVous pouvez recourir à cette aptitude autant de fois que votre modificateur de Charisme (minimum une fois). Vous récupérez ce quota en terminant un repos long.\nVotre dé d’Inspiration bardique évolue lorsque vous atteignez certains niveaux dans cette classe. Ce dé devient un d8 au niveau 5, un d10 au niveau 10 et un d12 au niveau 15.","Chant reposant (d12)":"À partir du niveau 2, vos mélodies apaisantes ou votre éloquence peuvent redonner vigueur à vos alliés blessés dans le cadre d’un repos court. Si vous ou toute créature amicale qui entend votre interprétation récupérez des points de vie en dépensant un ou plusieurs DV à la fin du repos court, chacune des créatures concernées récupère 1d6 points de vie supplémentaires.\nLa quantité de points de vie supplémentaires augmente quand vous atteignez certains niveaux dans cette classe : le dé passe à 1d8 au niveau 9, 1d10 au niveau 13 et 1d12 au niveau 17.","Inspiration supérieure":"Au niveau 20, quand vous jouez l’initiative alors qu’il ne vous reste plus aucune Inspiration bardique, vous en regagnez une."},"subs":{"Collège du savoir":[[3,"Maîtrises supplémentaires","Lorsque vous intégrez le Collège du Savoir au niveau 3, vous recevez la maîtrise de trois compétences de votre choix."],[3,"Mots cinglants","Également au niveau 3, vous apprenez à déconcentrer, perturber et miner la confiance d’autrui par votre sens de la répartie. Lorsqu’une créature que vous voyez dans un rayon de 18 m effectue un jet d’attaque, un test de caractéristique ou un jet de dégâts, vous pouvez jouer votre réaction pour dépenser l’une de vos Inspirations bardiques, lancer le dé correspondant et en soustraire le résultat au jet de la créature. Vous pouvez attendre que la créature ait effectué son jet avant de décider d’utiliser cette aptitude, à condition de ne pas attendre sciemment que le MJ annonce la réussite ou l’échec du jet d’attaque ou du test de caractéristique ni que la créature ait infligé ses dégâts. Une créature qui ne vous entend pas ou qui est immunisée contre l’état charmé n’est pas soumise à cet effet."],[6,"Secrets magiques supplémentaires","Au niveau 6, vous apprenez deux sorts de votre choix, issus de la liste de n’importe quelle classe. Chaque sort choisi doit être d’un niveau que vous pouvez lancer comme indiqué sur la table « Le barde » ou un sort mineur. Les sorts en question sont considérés dans votre cas comme des sorts de barde, mais ne sont pas décomptés de vos sorts connus"],[14,"Peerless Skill","Starting at 14th level, when you make an ability check, you can expend one use of Bardic Inspiration. Roll a Bardic Inspiration die and add the number rolled to your ability check. You can choose to do so after you roll the die for the ability check, but before the GM tells you whether you succeed or fail."]],"Collège de la vaillance":[[3,"Maîtrises supplémentaires","Armures intermédiaires, boucliers et armes de guerre."],[3,"Inspiration martiale","Un allié peut ajouter son dé d'Inspiration bardique aux dégâts d'une arme, ou à sa CA contre une attaque (réaction)."],[6,"Attaque supplémentaire","Tu attaques deux fois quand tu fais l'action Attaquer."],[14,"Magie de combat","Après avoir lancé un sort de barde avec ton action, tu peux faire une attaque d'arme en action bonus."]]}},"clerc":{"tab":[{"pb":2,"f":["Sorts : Clerc","Domaine divin","Sorts de domaine"],"x":[]},{"pb":2,"f":["Conduit divin (1/repos)","Conduit divin : Renvoi des morts-vivants","Aptitude de Domaine divin"],"x":[["Conduit divin",1]]},{"pb":2,"f":["Sorts de domaine"],"x":[["Conduit divin",1]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Conduit divin",1]]},{"pb":3,"f":["Sorts de domaine","Destruction des morts-vivants (FP 1/2 ou moins)"],"x":[["Conduit divin",1],["Destruction des morts-vivants","FP 0.5"]]},{"pb":3,"f":["Conduit divin (2/repos)","Aptitude de Domaine divin"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 0.5"]]},{"pb":3,"f":["Sorts de domaine"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 0.5"]]},{"pb":3,"f":["Amélioration de caractéristique","Destruction des morts-vivants (FP 1 ou moins)","Aptitude de Domaine divin"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 1"]]},{"pb":4,"f":["Sorts de domaine"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 1"]]},{"pb":4,"f":["Intervention divine"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 1"]]},{"pb":4,"f":["Destruction des morts-vivants (FP 2 ou moins)"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 2"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 2"]]},{"pb":5,"f":[],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 2"]]},{"pb":5,"f":["Destruction des morts-vivants (FP 3 ou moins)"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 3"]]},{"pb":5,"f":[],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 3"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 3"]]},{"pb":6,"f":["Destruction des morts-vivants (FP 4 ou moins)","Aptitude de Domaine divin"],"x":[["Conduit divin",2],["Destruction des morts-vivants","FP 4"]]},{"pb":6,"f":["Conduit divin (3/repos)"],"x":[["Conduit divin",3],["Destruction des morts-vivants","FP 4"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Conduit divin",3],["Destruction des morts-vivants","FP 4"]]},{"pb":6,"f":["Amélioration d’intervention divine"],"x":[["Conduit divin",3],["Destruction des morts-vivants","FP 4"]]}],"feats":{"Sorts : Clerc":"Porteur de puissance divine, vous pouvez lancer des sorts de clerc.","Domaine divin":"Choisissez un domaine lié à votre divinité, comme celui de la Vie. Ce domaine, détaillé en fin de la description de la classe, fournit des exemples de dieux qui lui sont associés. Ce choix vous octroie des sorts de domaine et autres aptitudes dès le niveau 1.\nIl vous octroie également d’autres applications de Conduit divin à l’acquisition de cette aptitude au niveau 2 et d’autres bénéfices aux niveaux 6, 8 et 17.","Sorts de domaine":"Chaque domaine s’accompagne d’une liste de sorts, les sorts de domaine, que vous recevez aux niveaux de clerc indiqués dans la description du domaine. Une fois que vous avez acquis un sort de domaine, il est toujours préparé en ce qui vous concerne et n’est pas décompté du nombre de sorts que vous pouvez préparer quotidiennement.\nSi vous disposez d’un sort de domaine qui ne figure pas sur la liste de sorts du clerc, il n’en est pas moins considéré comme un sort de clerc pour vous.","Conduit divin (1/repos)":"Au niveau 2, vous recevez la capacité de canaliser directement l’énergie de votre divinité et de transformer ce flux en effets magiques. Vous débutez avec deux effets de ce type : Renvoi des morts-vivants et un autre effet déterminé par votre domaine. Certains domaines vous octroient des effets supplémentaires au fil de votre progression en niveaux, comme indiqué dans leur description.\nLorsque vous recourez à votre Conduit divin, vous choisissez quel effet produire. Vous devez terminer un repos court ou long pour pouvoir réutiliser votre Conduit divin.\nCertains effets de Conduit divin entraînent des jets de sauvegarde. Lorsque vous recourez à un tel effet par cette classe, le DD correspondant est égal à votre DD de sauvegarde des sorts de clerc.\nÀ partir du niveau 6, vous pouvez utiliser deux fois votre Conduit divin entre deux repos (trois fois entre deux repos à partir du niveau 18). Lorsque vous terminez un repos court ou long, vous récupérez ce quota.","Conduit divin : Renvoi des morts-vivants":"Au prix d’une action, vous arborez votre symbole sacré en prononçant une prière condamnant les morts-vivants. Tout mort-vivant qui vous voit ou vous entend dans un rayon de 9 m de vous effectue un jet de sauvegarde de Sagesse. En cas d’échec, la créature est renvoyée pendant 1 minute ou jusqu’à ce qu’elle subisse des dégâts.\nUne créature renvoyée doit consacrer ses tours de jeu à s’éloigner le plus possible de vous et ne peut volontairement se déplacer vers un espace situé à 9 m ou moins de vous. Elle ne peut en outre pas jouer de réaction. Comme action, elle ne peut entreprendre que Foncer ou tenter de se libérer d’un effet qui l’empêche de se déplacer. Si elle n’a nulle part où aller, elle peut entreprendre l’action Esquiver.","Aptitude de Domaine divin":"Choisissez un domaine lié à votre divinité, comme celui de la Vie. Ce domaine, détaillé en fin de la description de la classe, fournit des exemples de dieux qui lui sont associés. Ce choix vous octroie des sorts de domaine et autres aptitudes dès le niveau 1.\nIl vous octroie également d’autres applications de Conduit divin à l’acquisition de cette aptitude au niveau 2 et d’autres bénéfices aux niveaux 6, 8 et 17.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Destruction des morts-vivants (FP 1/2 ou moins)":"À partir du niveau 5, lorsqu’un mort-vivant rate son jet de sauvegarde contre votre aptitude de Renvoi des morts-vivants, il est aussitôt détruit si son facteur de puissance est inférieur ou égal à un certain seuil, comme indiqué dans la table « Destruction des morts- vivants ».","Conduit divin (2/repos)":"À partir du niveau 6, vous pouvez utiliser deux fois votre Conduit divin entre deux repos (trois fois entre deux repos à partir du niveau 18). Lorsque vous terminez un repos court ou long, vous récupérez ce quota.","Destruction des morts-vivants (FP 1 ou moins)":"À partir du niveau 5, lorsqu’un mort-vivant rate son jet de sauvegarde contre votre aptitude de Renvoi des morts-vivants, il est aussitôt détruit si son facteur de puissance est inférieur ou égal à un certain seuil, comme indiqué dans la table « Destruction des morts- vivants ».","Intervention divine":"À partir du niveau 10 et en cas de besoin impérieux, vous pouvez faire appel à votre divinité afin qu’elle intercède en votre faveur.\nImplorer l’aide de votre divinité nécessite que vous y consacriez votre action. Décrivez le type d’assistance demandé et lancez un dé de pourcentage. Si le résultat obtenu est inférieur ou égal à votre niveau de clerc, votre divinité intervient. Le MJ détermine alors la nature de cette intervention ; les effets d’un sort de clerc ou d’un sort de domaine, par exemple, s’inscrivent bien dans cette logique.\nSi votre divinité intervient, vous ne pouvez plus recourir à cette aptitude pendant 7 jours. Si elle n’est pas intervenue, vous pourrez y recourir de nouveau après avoir terminé un repos long.\nAu niveau 20, la divinité répond automatiquement à votre appel, sans qu’il soit besoin de procéder à un jet.","Destruction des morts-vivants (FP 2 ou moins)":"À partir du niveau 5, lorsqu’un mort-vivant rate son jet de sauvegarde contre votre aptitude de Renvoi des morts-vivants, il est aussitôt détruit si son facteur de puissance est inférieur ou égal à un certain seuil, comme indiqué dans la table « Destruction des morts- vivants ».","Destruction des morts-vivants (FP 3 ou moins)":"À partir du niveau 5, lorsqu’un mort-vivant rate son jet de sauvegarde contre votre aptitude de Renvoi des morts-vivants, il est aussitôt détruit si son facteur de puissance est inférieur ou égal à un certain seuil, comme indiqué dans la table « Destruction des morts- vivants ».","Destruction des morts-vivants (FP 4 ou moins)":"À partir du niveau 5, lorsqu’un mort-vivant rate son jet de sauvegarde contre votre aptitude de Renvoi des morts-vivants, il est aussitôt détruit si son facteur de puissance est inférieur ou égal à un certain seuil, comme indiqué dans la table « Destruction des morts- vivants ».","Conduit divin (3/repos)":"À partir du niveau 6, vous pouvez utiliser deux fois votre Conduit divin entre deux repos (trois fois entre deux repos à partir du niveau 18). Lorsque vous terminez un repos court ou long, vous récupérez ce quota.","Amélioration d’intervention divine":"Au niveau 20, la divinité répond automatiquement à votre appel, sans qu’il soit besoin de procéder à un jet"},"subs":{"Vie":[[1,"Maîtrise supplémentaire","Lorsque vous optez pour ce domaine au niveau 1, vous recevez la maîtrise des armures lourdes."],[1,"Disciple de la Vie","Dès le niveau 1 également, vos sorts de guérison s’avèrent plus efficaces. Chaque fois que vous utilisez un sort du 1er niveau ou supérieur pour rendre des points de vie à une créature, celle-ci récupère un nombre de points de vie supplémentaires égal à 2 + le niveau du sort."],[2,"Conduit divin : Survivance","À partir du niveau 2, vous pouvez utiliser Conduit divin pour soigner les plus mal en point.\nAu prix d’une action, vous brandissez votre symbole sacré pour libérer des énergies curatives qui peuvent restaurer un nombre de points de vie égal au quintuple de votre niveau de clerc.\nChoisissez toutes les créatures que vous souhaitez dans un rayon de 9 m de vous et répartissez ces points de vie entre elles. Cette aptitude ne permet pas à une créature de dépasser la moitié de son maximum de points de vie. Vous ne pouvez pas utiliser cette aptitude sur un mort-vivant ou un artificiel."],[6,"Guérisseur béni","À partir du niveau 6, les sorts de guérison que vous lancez sur autrui vous soignent également. Lorsque vous lancez un sort du 1er niveau ou supérieur qui rend des points de vie à une créature autre que vous, vous récupérez un nombre de points de vie égal à 2 + le niveau du sort."],[8,"Impact divin","Au niveau 8, vous devenez apte à insuffler de l’énergie divine dans vos frappes. Une fois à chacun de vos tours, lorsque vous touchez une créature avec une attaque d’arme, vous pouvez faire en sorte que l’arme inflige 1d8 dégâts radiants supplémentaires à la cible. Lorsque vous atteignez le niveau 14, ces dégâts supplémentaires passent à 2d8."],[17,"Guérison suprême","À partir du niveau 17, quand vous êtes censé lancer un ou plusieurs dés pour faire regagner des points de vie par le biais d’un sort, la ou les cibles récupèrent le maximum possible pour chaque dé. Au lieu de rendre 2d6 points de vie à une créature, par exemple, vous lui en faites récupérer 12."]],"Duperie":[[1,"Bénédiction de l'escroc","Un allié touché a l'avantage aux tests de Discrétion pendant 1 heure. Sorts de domaine : charme-personne, déguisement, image miroir, passage sans trace, clignotement, dissipation de la magie, métamorphose, porte dimensionnelle, domination de personne, modification de mémoire."],[2,"Conduit divin : invocation de réplique","Tu crées un double illusoire mobile de toi-même pendant 1 minute ; tu peux lancer tes sorts depuis sa position et tu as l'avantage quand vous êtes tous deux près d'une cible."],[6,"Conduit divin : linceul d'ombre","Tu deviens invisible jusqu'à la fin de ton prochain tour."],[8,"Frappe divine","Une fois par tour, une attaque d'arme qui touche inflige +1d8 poison (2d8 au niveau 14)."],[17,"Réplique améliorée","Jusqu'à quatre doubles, déplaçables en action bonus."]],"Guerre":[[1,"Maîtrises supplémentaires","Armes de guerre et armures lourdes. Sorts de domaine : bouclier de la foi, faveur divine, arme magique, arme spirituelle, aura du croisé, esprits gardiens, liberté de mouvement, peau de pierre, colonne de flamme, immobilisation de monstre."],[1,"Prêtre de guerre","Après l'action Attaquer, une attaque d'arme en action bonus. Utilisations = modificateur de Sagesse par repos long."],[2,"Conduit divin : frappe guidée","+10 à un jet d'attaque après l'avoir vu."],[6,"Conduit divin : bénédiction du dieu de la guerre","En réaction, +10 au jet d'attaque d'une créature à 9 m."],[8,"Frappe divine","Une fois par tour, une attaque d'arme qui touche inflige +1d8 du type de l'arme (2d8 au niveau 14)."],[17,"Avatar de bataille","Résistance aux dégâts contondants, perforants et tranchants des armes non magiques."]],"Lumière":[[1,"Sort mineur supplémentaire","Tu connais le sort Lumière. Sorts de domaine : lueurs féeriques, mains brûlantes, rayon ardent, sphère de feu, boule de feu, lumière du jour, gardien de la foi, mur de feu, colonne de flamme, scrutation."],[1,"Illumination protectrice","En réaction, un attaquant à 9 m a un désavantage. Utilisations = modificateur de Sagesse par repos long."],[2,"Conduit divin : radiance de l'aube","Dissipe les ténèbres magiques à 9 m ; les ennemis font un jet de Constitution : 2d10 + niveau de clerc radiants (moitié si réussi)."],[6,"Illumination améliorée","Illumination protectrice protège aussi les autres créatures proches."],[8,"Incantation puissante","+ modificateur de Sagesse aux dégâts de tes sorts mineurs de clerc."],[17,"Halo de lumière","Aura de lumière solaire : les ennemis ont un désavantage aux sauvegardes contre tes sorts de feu et radiants."]],"Nature":[[1,"Acolyte de la nature","Un sort mineur de druide et une maîtrise (Dressage, Nature ou Survie). Maîtrise des armures lourdes. Sorts de domaine : amitié avec les animaux, communication avec les animaux, croissance d'épines, peau d'écorce, croissance végétale, mur de vent, domination de bête, liane avide, fléau d'insectes, passage par les arbres."],[2,"Conduit divin : charme des animaux et des plantes","Bêtes et plantes à 9 m font un jet de Sagesse ou sont charmées 1 minute."],[6,"Atténuation des éléments","En réaction, une créature à 9 m résiste à l'acide, au froid, au feu, à la foudre ou au tonnerre contre une attaque."],[8,"Frappe divine","Une fois par tour, +1d8 froid, feu ou foudre avec une arme (2d8 au niveau 14)."],[17,"Maître de la nature","En action bonus, tu commandes les bêtes et plantes charmées."]],"Savoir":[[1,"Bénédictions du savoir","Deux langues et deux compétences (Arcanes, Histoire, Nature, Religion) avec bonus de maîtrise doublé. Sorts de domaine : identification, injonction, augure, suggestion, antidétection, communication avec les morts, confusion, œil magique, mythes et légendes, scrutation."],[2,"Conduit divin : savoir ancestral","Maîtrise d'une compétence ou d'un outil pendant 10 minutes."],[6,"Conduit divin : lecture des pensées","Jet de Sagesse ou tu lis les pensées de la cible ; tu peux ensuite lui lancer Suggestion sans emplacement."],[8,"Incantation puissante","+ modificateur de Sagesse aux dégâts de tes sorts mineurs de clerc."],[17,"Visions du passé","En méditant, tu vois le passé d'un objet ou d'un lieu."]],"Tempête":[[1,"Maîtrises supplémentaires","Armes de guerre et armures lourdes. Sorts de domaine : nappe de brouillard, vague tonnante, bourrasque, fracassement, appel de la foudre, tempête de neige, contrôle de l'eau, tempête de grêle, fléau d'insectes, vague destructrice."],[1,"Fureur de l'ouragan","En réaction quand on te touche au contact : jet de Dextérité de l'attaquant ou 2d8 foudre/tonnerre. Utilisations = modificateur de Sagesse par repos long."],[2,"Conduit divin : fureur destructrice","Dégâts de foudre ou de tonnerre au maximum au lieu de les lancer."],[6,"Frappe de l'éclair","Quand tu infliges des dégâts de foudre à une créature Grande ou plus petite, tu peux la repousser de 3 m."],[8,"Frappe divine","Une fois par tour, +1d8 tonnerre avec une arme (2d8 au niveau 14)."],[17,"Enfant de la tempête","Vitesse de vol égale à ta vitesse en extérieur."]],"Forge":[[1,"Bénédiction de la forge","Maîtrise des armures lourdes et outils de forgeron. Après un repos long, une arme ou armure gagne +1 jusqu'au prochain repos long. Sorts de domaine : châtiment calcinant, identification, arme magique, métal brûlant, arme élémentaire, protection contre une énergie, fabrication, mur de feu, animation d'objets, création."],[2,"Conduit divin : bénédiction de l'artisan","Rituel d'une heure : tu crées un objet de métal non magique (100 po max)."],[6,"Âme de la forge","Résistance au feu et +1 CA en armure lourde."],[8,"Frappe divine","Une fois par tour, +1d8 feu avec une arme (2d8 au niveau 14)."],[17,"Saint de la forge et du feu","Immunité au feu ; en armure lourde, résistance aux armes non magiques."]]}},"druide":{"tab":[{"pb":2,"f":["Sorts : Druide","Druidique"],"x":[["Forme sauvage","FP 0 max"]]},{"pb":2,"f":["Forme sauvage (FP 1/4 ou moins, ni vitesse de vol ni de nage)","Cercle druidique"],"x":[["Forme sauvage","FP 1/4 max"]]},{"pb":2,"f":[],"x":[["Forme sauvage","FP 1/4 max"]]},{"pb":2,"f":["Forme sauvage (FP 1/2 ou moins, pas de vitesse de vol)","Amélioration de caractéristique"],"x":[["Forme sauvage","FP 1/2 max, nage"]]},{"pb":3,"f":[],"x":[["Forme sauvage","FP 1/2 max, nage"]]},{"pb":3,"f":["Amélioration de cercle druidique"],"x":[["Forme sauvage","FP 1/2 max, nage"]]},{"pb":3,"f":[],"x":[["Forme sauvage","FP 1 max, nage"]]},{"pb":3,"f":["Forme sauvage (FP 1 ou moins)","Amélioration de caractéristique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":4,"f":[],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":4,"f":["Amélioration de cercle druidique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":4,"f":[],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":5,"f":[],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":5,"f":["Amélioration de cercle druidique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":5,"f":[],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":6,"f":[],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":6,"f":["Jeunesse éternelle","Incantation animale"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]},{"pb":6,"f":["Archidruide"],"x":[["Forme sauvage","FP 1 max, nage, vol"]]}],"feats":{"Sorts : Druide":"Vos pouvoirs découlant de l’essence divine de la nature elle-même, les sorts que vous lancez vous permettent de façonner cette essence à votre gré.","Druidique":"Vous connaissez le druidique, la langue secrète des druides. Vous pouvez parler cette langue et l’utiliser pour laisser des messages cachés. Vous-même et tous ceux qui connaissent cette langue repérez automatiquement de tels messages. D’autres peuvent aussi détecter la présence d’un tel message en réussissant un test de Sagesse (Perception) DD 15, mais sont incapables d’en déchiffrer la signification.","Forme sauvage (FP 1/4 ou moins, ni vitesse de vol ni de nage)":"À partir du niveau 2, vous pouvez consacrer votre action à prendre magiquement la forme d’une bête que vous avez déjà vue. Vous pouvez recourir à cette aptitude deux fois. Lorsque vous terminez un repos court ou long, vous récupérez ce quota.\nVotre niveau de druide détermine les bêtes dont vous pouvez assumer la forme, comme indiqué dans la table « Formes sauvages ». Au niveau 2, par exemple, vous pouvez vous transformer en n’importe quelle bête dont le facteur de puissance est inférieur ou égal à 1/4 et qui ne possède ni vitesse de vol ni vitesse de nage.\nVous pouvez rester sous forme sauvage un nombre d’heures égal à la moitié de votre niveau de druide, arrondi à l’inférieur. Vous reprenez alors votre forme normale, à moins que vous ne dépensiez une autre utilisation de cette aptitude. Vous pouvez revenir à votre forme normale plus tôt par une action bonus à votre tour. Vous retrouvez automatiquement votre forme normale si vous vous retrouvez inconscient, tombez à 0 point de vie ou si vous mourez.\nTant que vous êtes transformé, les règles suivantes s’appliquent :\n- Votre profil de jeu est remplacé par celui de la bête dont vous assumez la forme, mais vous conservez votre alignement, votre personnalité et vos valeurs d’Intelligence, de Sagesse et de Charisme. Vous conservez également toutes vos maîtrises de compétence et de jets de sauvegarde, en plus de recevoir celles de la créature. Si la créature possède une maîtrise identique à l’une des vôtres, mais avec un bonus supérieur au vôtre dans son profil, son bonus s’applique à la place du vôtre. Si cette créature possède des actions légendaires ou d’antre, vous ne pouvez en revanche pas y recourir.\n- Sous forme sauvage, vous adoptez aussi les points de vie et dés de vie de la bête. Lorsque vous retrouvez votre forme normale, vous revenez au nombre de points de vie que vous aviez avant la métamorphose. Si, en revanche, ce retour est dû au fait que vous êtes tombé à 0 point de vie, tous les dégâts excédentaires sont répercutés sur votre forme normale. Si, par exemple, vous subissez 10 dégâts sous forme animale et qu’il ne vous reste plus que 1 point de vie, vous subissez 9 dégâts en retrouvant votre forme normale. Tant que ces dégâts excédentaires ne réduisent pas votre forme normale à 0 point de vie, vous ne subissez pas l’état inconscient.\n- Vous ne pouvez pas lancer de sorts, et votre capacité à parler ou à effectuer toute action nécessitant des mains se limite aux possibilités offertes par votre forme animale. Cependant, cette métamorphose ne brise pas votre concentration sur un sort que vous aviez lancé auparavant et ne vous empêche pas d’effectuer les actions faisant partie d’un sort, comme appel de la foudre, que vous auriez déjà lancé.\n- Vous conservez l’usage de toutes les aptitudes de votre classe, race ou autre source et pouvez les utiliser si la nouvelle forme est physiquement apte à le faire. Cependant, vous ne pouvez recourir à aucun de vos sens spéciaux, tels que la vision dans le noir, sauf si votre nouvelle forme en dispose aussi.\n- Vous décidez si votre équipement tombe au sol dans votre espace, fusionne avec votre nouvelle forme ou est porté par elle. L’équipement porté fonctionne normalement, mais c’est au MJ de décider si une pièce d’équipement donnée peut être portée par la créature, en fonction de la forme et de la taille de celle-ci. Votre équipement ne change pas de taille ou de forme pour s’adapter à votre silhouette animale ; toute pièce d’équipement que la forme sauvage ne peut pas porter doit soit tomber au sol, soit fusionner avec elle. L’équipement qui fusionne avec vous sous votre forme animale n’a aucun effet jusqu’à ce que vous retrouviez votre forme normale.","Cercle druidique":"Parvenu au niveau 2, vous décidez d’adopter les valeurs d’un cercle de druides, comme le Cercle de la Terre. Ce choix vous octroie des aptitudes au niveau 2, puis aux niveaux 6, 10 et 14.","Forme sauvage (FP 1/2 ou moins, pas de vitesse de vol)":"À partir du niveau 2, vous pouvez consacrer votre action à prendre magiquement la forme d’une bête que vous avez déjà vue. Vous pouvez recourir à cette aptitude deux fois. Lorsque vous terminez un repos court ou long, vous récupérez ce quota.\nVotre niveau de druide détermine les bêtes dont vous pouvez assumer la forme, comme indiqué dans la table « Formes sauvages ». Au niveau 2, par exemple, vous pouvez vous transformer en n’importe quelle bête dont le facteur de puissance est inférieur ou égal à 1/4 et qui ne possède ni vitesse de vol ni vitesse de nage.\nVous pouvez rester sous forme sauvage un nombre d’heures égal à la moitié de votre niveau de druide, arrondi à l’inférieur. Vous reprenez alors votre forme normale, à moins que vous ne dépensiez une autre utilisation de cette aptitude. Vous pouvez revenir à votre forme normale plus tôt par une action bonus à votre tour. Vous retrouvez automatiquement votre forme normale si vous vous retrouvez inconscient, tombez à 0 point de vie ou si vous mourez.\nTant que vous êtes transformé, les règles suivantes s’appliquent :\n- Votre profil de jeu est remplacé par celui de la bête dont vous assumez la forme, mais vous conservez votre alignement, votre personnalité et vos valeurs d’Intelligence, de Sagesse et de Charisme. Vous conservez également toutes vos maîtrises de compétence et de jets de sauvegarde, en plus de recevoir celles de la créature. Si la créature possède une maîtrise identique à l’une des vôtres, mais avec un bonus supérieur au vôtre dans son profil, son bonus s’applique à la place du vôtre. Si cette créature possède des actions légendaires ou d’antre, vous ne pouvez en revanche pas y recourir.\n- Sous forme sauvage, vous adoptez aussi les points de vie et dés de vie de la bête. Lorsque vous retrouvez votre forme normale, vous revenez au nombre de points de vie que vous aviez avant la métamorphose. Si, en revanche, ce retour est dû au fait que vous êtes tombé à 0 point de vie, tous les dégâts excédentaires sont répercutés sur votre forme normale. Si, par exemple, vous subissez 10 dégâts sous forme animale et qu’il ne vous reste plus que 1 point de vie, vous subissez 9 dégâts en retrouvant votre forme normale. Tant que ces dégâts excédentaires ne réduisent pas votre forme normale à 0 point de vie, vous ne subissez pas l’état inconscient.\n- Vous ne pouvez pas lancer de sorts, et votre capacité à parler ou à effectuer toute action nécessitant des mains se limite aux possibilités offertes par votre forme animale. Cependant, cette métamorphose ne brise pas votre concentration sur un sort que vous aviez lancé auparavant et ne vous empêche pas d’effectuer les actions faisant partie d’un sort, comme appel de la foudre, que vous auriez déjà lancé.\n- Vous conservez l’usage de toutes les aptitudes de votre classe, race ou autre source et pouvez les utiliser si la nouvelle forme est physiquement apte à le faire. Cependant, vous ne pouvez recourir à aucun de vos sens spéciaux, tels que la vision dans le noir, sauf si votre nouvelle forme en dispose aussi.\n- Vous décidez si votre équipement tombe au sol dans votre espace, fusionne avec votre nouvelle forme ou est porté par elle. L’équipement porté fonctionne normalement, mais c’est au MJ de décider si une pièce d’équipement donnée peut être portée par la créature, en fonction de la forme et de la taille de celle-ci. Votre équipement ne change pas de taille ou de forme pour s’adapter à votre silhouette animale ; toute pièce d’équipement que la forme sauvage ne peut pas porter doit soit tomber au sol, soit fusionner avec elle. L’équipement qui fusionne avec vous sous votre forme animale n’a aucun effet jusqu’à ce que vous retrouviez votre forme normale.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Amélioration de cercle druidique":"Parvenu au niveau 2, vous décidez d’adopter les valeurs d’un cercle de druides, comme le Cercle de la Terre. Ce choix vous octroie des aptitudes au niveau 2, puis aux niveaux 6, 10 et 14.","Forme sauvage (FP 1 ou moins)":"À partir du niveau 2, vous pouvez consacrer votre action à prendre magiquement la forme d’une bête que vous avez déjà vue. Vous pouvez recourir à cette aptitude deux fois. Lorsque vous terminez un repos court ou long, vous récupérez ce quota.\nVotre niveau de druide détermine les bêtes dont vous pouvez assumer la forme, comme indiqué dans la table « Formes sauvages ». Au niveau 2, par exemple, vous pouvez vous transformer en n’importe quelle bête dont le facteur de puissance est inférieur ou égal à 1/4 et qui ne possède ni vitesse de vol ni vitesse de nage.\nVous pouvez rester sous forme sauvage un nombre d’heures égal à la moitié de votre niveau de druide, arrondi à l’inférieur. Vous reprenez alors votre forme normale, à moins que vous ne dépensiez une autre utilisation de cette aptitude. Vous pouvez revenir à votre forme normale plus tôt par une action bonus à votre tour. Vous retrouvez automatiquement votre forme normale si vous vous retrouvez inconscient, tombez à 0 point de vie ou si vous mourez.\nTant que vous êtes transformé, les règles suivantes s’appliquent :\n- Votre profil de jeu est remplacé par celui de la bête dont vous assumez la forme, mais vous conservez votre alignement, votre personnalité et vos valeurs d’Intelligence, de Sagesse et de Charisme. Vous conservez également toutes vos maîtrises de compétence et de jets de sauvegarde, en plus de recevoir celles de la créature. Si la créature possède une maîtrise identique à l’une des vôtres, mais avec un bonus supérieur au vôtre dans son profil, son bonus s’applique à la place du vôtre. Si cette créature possède des actions légendaires ou d’antre, vous ne pouvez en revanche pas y recourir.\n- Sous forme sauvage, vous adoptez aussi les points de vie et dés de vie de la bête. Lorsque vous retrouvez votre forme normale, vous revenez au nombre de points de vie que vous aviez avant la métamorphose. Si, en revanche, ce retour est dû au fait que vous êtes tombé à 0 point de vie, tous les dégâts excédentaires sont répercutés sur votre forme normale. Si, par exemple, vous subissez 10 dégâts sous forme animale et qu’il ne vous reste plus que 1 point de vie, vous subissez 9 dégâts en retrouvant votre forme normale. Tant que ces dégâts excédentaires ne réduisent pas votre forme normale à 0 point de vie, vous ne subissez pas l’état inconscient.\n- Vous ne pouvez pas lancer de sorts, et votre capacité à parler ou à effectuer toute action nécessitant des mains se limite aux possibilités offertes par votre forme animale. Cependant, cette métamorphose ne brise pas votre concentration sur un sort que vous aviez lancé auparavant et ne vous empêche pas d’effectuer les actions faisant partie d’un sort, comme appel de la foudre, que vous auriez déjà lancé.\n- Vous conservez l’usage de toutes les aptitudes de votre classe, race ou autre source et pouvez les utiliser si la nouvelle forme est physiquement apte à le faire. Cependant, vous ne pouvez recourir à aucun de vos sens spéciaux, tels que la vision dans le noir, sauf si votre nouvelle forme en dispose aussi.\n- Vous décidez si votre équipement tombe au sol dans votre espace, fusionne avec votre nouvelle forme ou est porté par elle. L’équipement porté fonctionne normalement, mais c’est au MJ de décider si une pièce d’équipement donnée peut être portée par la créature, en fonction de la forme et de la taille de celle-ci. Votre équipement ne change pas de taille ou de forme pour s’adapter à votre silhouette animale ; toute pièce d’équipement que la forme sauvage ne peut pas porter doit soit tomber au sol, soit fusionner avec elle. L’équipement qui fusionne avec vous sous votre forme animale n’a aucun effet jusqu’à ce que vous retrouviez votre forme normale.","Jeunesse éternelle":"À partir du niveau 18, la magie primitive que vous maniez ralentit votre vieillissement. Pour chaque décennie qui passe, votre corps ne vieillit que d’un an.","Incantation animale":"À partir du niveau 18, vous pouvez lancer la plupart de vos sorts de druide, quelle que soit la forme que vous adoptez via l’aptitude Forme sauvage. Vous pouvez accomplir les composantes somatiques et verbales d’un sort de druide sous forme de bête, mais n’êtes pas en mesure de fournir ses composantes matérielles.","Archidruide":"Au niveau 20, vous pouvez désormais utiliser Forme sauvage à volonté.\nEn outre, vous ne tenez plus compte des composantes verbales et somatiques de vos sorts de druide, ainsi que des composantes matérielles qui n’ont pas de coût et ne sont pas détruites par le sort. Ce bénéfice s’applique sous toutes vos formes, normale comme animale par le biais de Forme sauvage."},"subs":{"Cercle de la terre":[[2,"Sort mineur supplémentaire","Quand vous choisissez ce cercle au niveau 2, vous apprenez un sort mineur de druide supplémentaire de votre choix."],[2,"Ressourcement","À partir du niveau 2, vous pouvez récupérer une partie de votre énergie magique en méditant assis et en communiant avec la nature. Pendant un repos court, choisissez quels emplacements de sort dépensés vous souhaitez récupérer. La somme des niveaux de ces emplacements de sort dépensés ne doit pas excéder la moitié de votre niveau de druide (arrondie au supérieur), et aucun de ces emplacements ne doit être du 6e niveau ou supérieur. Une fois que vous avez utilisé cette aptitude, vous devez terminer un repos long pour pouvoir y recourir de nouveau.\nExemple : en tant que druide de niveau 4, vous pouvez récupérer jusqu’à deux niveaux d’emplace- ments de sort. Il peut s’agir d’un emplacement du 2e niveau ou de deux emplacements du 1er niveau."],[6,"Foulée tellurique","À partir du niveau 6, vous déplacer sur un terrain difficile non magique ne vous coûte aucun déplacement supplémentaire. Vous pouvez également traverser la végétation non magique sans être ralenti par elle ni subir de dégâts si elle possède des épines, des aiguilles ou tout autre danger comparable.\nVous êtes en outre avantagé aux jets de sauvegarde contre les plantes créées ou manipulées magiquement afin d’empêcher le déplacement, comme celles que produit le sort enchevêtrement."],[10,"Protégé de dame Nature","Parvenu au niveau 10, vous ne pouvez plus être charmé ni effrayé par les élémentaires et les fées, et vous êtes immunisé contre le poison et les maladies."],[14,"Sanctuaire de dame Nature","Quand vous atteignez le niveau 14, les créatures du monde naturel perçoivent votre lien avec la nature et hésitent à vous attaquer. Quand une bête ou une plante vous attaque, cette créature effectue un jet de sauvegarde de Sagesse contre le DD de sauvegarde de vos sorts de druide. En cas d’échec, la créature doit choisir une autre cible, sans quoi l’attaque rate automatiquement. En cas de réussite, elle est immunisée contre cet effet pendant 24 heures.\nLa créature a conscience de cet effet avant de lancer son attaque contre vous."]],"Cercle de la lune":[[2,"Forme sauvage de combat","Forme sauvage en action bonus ; sous forme de bête, dépense un emplacement pour récupérer 1d8 PV par niveau d'emplacement."],[2,"Formes du cercle","Bêtes de FP 1 dès le niveau 2, puis FP = niveau ÷ 3 à partir du niveau 6."],[6,"Frappe primitive","Tes attaques sous forme de bête sont magiques."],[10,"Forme sauvage élémentaire","Deux utilisations de forme sauvage pour devenir un élémentaire (air, terre, feu, eau)."],[14,"Mille formes","Modification d'apparence à volonté."]]}},"guerrier":{"tab":[{"pb":2,"f":["Style de combat","Second souffle"],"x":[]},{"pb":2,"f":["Fougue (1 utilisation)"],"x":[["Fougue",1]]},{"pb":2,"f":["Archétype martial"],"x":[["Fougue",1]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Fougue",1]]},{"pb":3,"f":["Attaque supplémentaire"],"x":[["Fougue",1],["Attaques par action",2]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Fougue",1],["Attaques par action",2]]},{"pb":3,"f":["Amélioration d’archétype martial"],"x":[["Fougue",1],["Attaques par action",2]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Fougue",1],["Attaques par action",2]]},{"pb":4,"f":["Inflexible (1 utilisation)"],"x":[["Fougue",1],["Inflexible",1],["Attaques par action",2]]},{"pb":4,"f":["Amélioration d’archétype martial"],"x":[["Fougue",1],["Inflexible",1],["Attaques par action",2]]},{"pb":4,"f":["Attaque supplémentaire (2)"],"x":[["Fougue",1],["Inflexible",1],["Attaques par action",3]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Fougue",1],["Inflexible",1],["Attaques par action",3]]},{"pb":5,"f":["Inflexible (2 utilisations)"],"x":[["Fougue",1],["Inflexible",2],["Attaques par action",3]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Fougue",1],["Inflexible",2],["Attaques par action",3]]},{"pb":5,"f":["Amélioration d’archétype martial"],"x":[["Fougue",1],["Inflexible",2],["Attaques par action",3]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Fougue",1],["Inflexible",2],["Attaques par action",3]]},{"pb":6,"f":["Fougue (2 utilisations)","Inflexible (3 utilisations)"],"x":[["Fougue",2],["Inflexible",3],["Attaques par action",3]]},{"pb":6,"f":["Amélioration d’archétype martial"],"x":[["Fougue",2],["Inflexible",3],["Attaques par action",3]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Fougue",2],["Inflexible",3],["Attaques par action",3]]},{"pb":6,"f":["Attaque supplémentaire (3)"],"x":[["Fougue",2],["Inflexible",3],["Attaques par action",4]]}],"feats":{"Style de combat":"Vous choisissez de vous spécialiser dans un style de combat particulier. Choisissez l’une des options suivantes. Vous ne pouvez pas opter plus d’une fois pour un même Style de combat, si vous avez de nouveau la possibilité d’en choisir un.\n\n• Style de combat : Archerie : Vous recevez un bonus de +2 aux jets d’attaque effectués avec des armes à distance.\n\n• Style de combat : Défense : Tant que vous portez une armure, vous recevez un bonus de +1 en CA.\n\n• Style de combat : Duel : Lorsque vous maniez une arme de corps à corps dans une main et aucune autre arme, vous recevez un bonus de +2 aux jets de dégâts de cette arme.\n\n• Style de combat : Armes à deux mains : Lorsque vous obtenez un 1 ou un 2 sur un dé de dégâts d’une attaque effectuée avec une arme de corps à corps que vous tenez à deux mains, vous pouvez relancer ce dé, auquel cas c’est le nouveau jet qui s’applique, même si vous obtenez 1 ou 2. Pour que vous puissiez recevoir ce bénéfice, l’arme doit afficher la propriété « deux mains » ou « polyvalente ».\n\n• Style de combat : Protection : Lorsqu’une créature que vous voyez attaque une cible autre que vous située dans un rayon de 1,50 m de vous, vous pouvez jouer votre réaction pour lui imposer le désavantage au jet d’attaque. Vous devez porter un bouclier.\n\n• Style de combat : Combat à deux armes : Lorsque vous combattez avec deux armes, vous pouvez ajouter votre modificateur de caractéristique aux dégâts de la seconde attaque.","Second souffle":"Vous disposez d’une réserve limitée d’endurance dans laquelle vous pouvez puiser pour préserver votre intégrité. À votre tour, vous pouvez par une action bonus récupérer un nombre de points de vie égal à 1d10 + votre niveau de guerrier. Une fois que vous avez utilisé cette aptitude, vous devez terminer un repos court ou long pour pouvoir y recourir de nouveau.","Fougue (1 utilisation)":"À partir du niveau 2, vous pouvez vous dépasser pendant quelques instants. À votre tour, vous pouvez entreprendre une action supplémentaire en plus de votre action normale et d’une éventuelle action bonus.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos court ou long pour pouvoir y recourir de nouveau. À partir du niveau 17, vous pouvez l’utiliser deux fois avant de devoir terminer un repos, mais dans la limite d’une seule fois lors d’un même tour.","Archétype martial":"Au niveau 3, vous choisissez un archétype, sorte d’idéal martial que vous vous efforcez de reproduire par votre technique et votre style, comme Champion. L’archétype choisi vous octroie des aptitudes au niveau 3, puis aux niveaux 7, 10, 15 et 18.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 6, 8, 12, 14, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Attaque supplémentaire":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.\nLe nombre d’attaques dans le cadre de l’action Attaquer passe à trois quand vous atteignez le niveau 11, puis à quatre quand vous atteignez le niveau 20 dans cette classe.","Amélioration d’archétype martial":"Au niveau 3, vous choisissez un archétype, sorte d’idéal martial que vous vous efforcez de reproduire par votre technique et votre style, comme Champion. L’archétype choisi vous octroie des aptitudes au niveau 3, puis aux niveaux 7, 10, 15 et 18.","Inflexible (1 utilisation)":"À partir du niveau 9, vous pouvez relancer un jet de sauvegarde en cas d’échec. Si vous faites ce choix, c’est forcément le nouveau jet qui s’applique et vous devez ensuite terminer un repos long avant de pouvoir recourir de nouveau à cette aptitude.\nVous pouvez recourir deux fois à cette aptitude entre deux repos longs au niveau 13 et trois fois entre deux repos longs à partir du niveau 17.","Attaque supplémentaire (2)":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.\nLe nombre d’attaques dans le cadre de l’action Attaquer passe à trois quand vous atteignez le niveau 11, puis à quatre quand vous atteignez le niveau 20 dans cette classe.","Inflexible (2 utilisations)":"À partir du niveau 9, vous pouvez relancer un jet de sauvegarde en cas d’échec. Si vous faites ce choix, c’est forcément le nouveau jet qui s’applique et vous devez ensuite terminer un repos long avant de pouvoir recourir de nouveau à cette aptitude.\nVous pouvez recourir deux fois à cette aptitude entre deux repos longs au niveau 13 et trois fois entre deux repos longs à partir du niveau 17.","Fougue (2 utilisations)":"À partir du niveau 2, vous pouvez vous dépasser pendant quelques instants. À votre tour, vous pouvez entreprendre une action supplémentaire en plus de votre action normale et d’une éventuelle action bonus.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos court ou long pour pouvoir y recourir de nouveau. À partir du niveau 17, vous pouvez l’utiliser deux fois avant de devoir terminer un repos, mais dans la limite d’une seule fois lors d’un même tour.","Inflexible (3 utilisations)":"À partir du niveau 9, vous pouvez relancer un jet de sauvegarde en cas d’échec. Si vous faites ce choix, c’est forcément le nouveau jet qui s’applique et vous devez ensuite terminer un repos long avant de pouvoir recourir de nouveau à cette aptitude.\nVous pouvez recourir deux fois à cette aptitude entre deux repos longs au niveau 13 et trois fois entre deux repos longs à partir du niveau 17.","Attaque supplémentaire (3)":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.\nLe nombre d’attaques dans le cadre de l’action Attaquer passe à trois quand vous atteignez le niveau 11, puis à quatre quand vous atteignez le niveau 20 dans cette classe."},"subs":{"Champion":[[3,"Critique amélioré","Dès que vous choisissez cet archétype au niveau 3, vos attaques d’arme infligent un coup critique si le résultat du dé est de 19 ou 20."],[7,"Athlète accompli","À partir du niveau 7, vous pouvez ajouter la moitié de votre bonus de maîtrise (arrondi au supérieur) à tous vos tests de Force, de Dextérité ou de Constitution auxquels vous n’appliquez pas déjà votre bonus de maîtrise.\nPar ailleurs, lorsque vous effectuez un saut en longueur avec élan, la distance couverte augmente de 30 cm par point de modificateur de Force."],[10,"Style de combat supplémentaire","Au niveau 10, vous pouvez choisir un second style de combat dans la liste de cette aptitude de classe."],[15,"Critique supérieur","À partir du niveau 15, vos attaques d’arme obtiennent un coup critique sur un résultat du dé de 18 à 20."],[18,"Survivant","Au niveau 18, vous atteignez le summum de votre endurance au combat. Au début de chacun de vos tours et à la condition qu’il ne vous reste pas plus de la moitié de vos points de vie, vous regagnez un nombre de points de vie égal à 5 + votre modificateur de Constitution. Vous ne bénéficiez pas de cette aptitude si vous avez 0 point de vie."]],"Maître de guerre":[[3,"Supériorité martiale","Trois manœuvres et quatre dés de supériorité (d8), récupérés au repos court. DD = 8 + maîtrise + mod. de For ou Dex. Maîtrise d'un outil d'artisan."],[7,"Observation de l'ennemi","Après 1 minute d'observation, tu compares une créature à toi sur deux caractéristiques."],[10,"Supériorité martiale améliorée","Dés de supériorité en d10 (d12 au niveau 18)."],[15,"Implacable","Si tu n'as plus de dé de supériorité au jet d'initiative, tu en récupères un."]],"Chevalier occulte":[[3,"Incantation","Sorts de magicien (abjuration et évocation surtout), caractéristique : Intelligence."],[3,"Lien avec une arme","Rituel d'une heure : jusqu'à deux armes liées, impossibles à désarmer, invocables en action bonus."],[7,"Magie de guerre","Après un sort mineur en action, une attaque d'arme en action bonus."],[10,"Frappe occulte","Une créature touchée a un désavantage à sa prochaine sauvegarde contre ton sort."],[15,"Charge arcanique","Avec Fougue, tu peux te téléporter de 9 m."],[18,"Magie de guerre améliorée","Après un sort en action, une attaque d'arme en action bonus."]]}},"moine":{"tab":[{"pb":2,"f":["Défense sans armure","Arts martiaux"],"x":[["Arts martiaux","1d4"]]},{"pb":2,"f":["Le Ki","Déluge de coups","Défense patiente","Porté par le vent","Déplacement sans armure"],"x":[["Arts martiaux","1d4"],["Ki",2],["Déplacement sans armure","+3 m"]]},{"pb":2,"f":["Tradition monastique","Parade de projectiles"],"x":[["Arts martiaux","1d4"],["Ki",3],["Déplacement sans armure","+3 m"]]},{"pb":2,"f":["Amélioration de caractéristique","Chute ralentie"],"x":[["Arts martiaux","1d4"],["Ki",4],["Déplacement sans armure","+3 m"]]},{"pb":3,"f":["Attaque supplémentaire","Frappe étourdissante"],"x":[["Arts martiaux","1d6"],["Ki",5],["Déplacement sans armure","+3 m"]]},{"pb":3,"f":["Frappes de ki","Amélioration de tradition monastique"],"x":[["Arts martiaux","1d6"],["Ki",6],["Déplacement sans armure","+4,5 m"]]},{"pb":3,"f":["Esquive totale","Sérénité"],"x":[["Arts martiaux","1d6"],["Ki",7],["Déplacement sans armure","+4,5 m"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Arts martiaux","1d6"],["Ki",8],["Déplacement sans armure","+4,5 m"]]},{"pb":4,"f":["Unarmored Movement"],"x":[["Arts martiaux","1d6"],["Ki",9],["Déplacement sans armure","+4,5 m"]]},{"pb":4,"f":["Pureté physique"],"x":[["Arts martiaux","1d6"],["Ki",10],["Déplacement sans armure","+6 m"]]},{"pb":4,"f":["Amélioration de tradition monastique"],"x":[["Arts martiaux","1d8"],["Ki",11],["Déplacement sans armure","+6 m"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Arts martiaux","1d8"],["Ki",12],["Déplacement sans armure","+6 m"]]},{"pb":5,"f":["Langage du soleil et de la lune"],"x":[["Arts martiaux","1d8"],["Ki",13],["Déplacement sans armure","+6 m"]]},{"pb":5,"f":["Âme de diamant"],"x":[["Arts martiaux","1d8"],["Ki",14],["Déplacement sans armure","+7,5 m"]]},{"pb":5,"f":["Jeunesse éternelle"],"x":[["Arts martiaux","1d8"],["Ki",15],["Déplacement sans armure","+7,5 m"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Arts martiaux","1d8"],["Ki",16],["Déplacement sans armure","+7,5 m"]]},{"pb":6,"f":["Amélioration de tradition monastique"],"x":[["Arts martiaux","1d10"],["Ki",17],["Déplacement sans armure","+7,5 m"]]},{"pb":6,"f":["Désertion de l’âme"],"x":[["Arts martiaux","1d10"],["Ki",18],["Déplacement sans armure","+9 m"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Arts martiaux","1d10"],["Ki",19],["Déplacement sans armure","+9 m"]]},{"pb":6,"f":["Perfection de l’être"],"x":[["Arts martiaux","1d10"],["Ki",20],["Déplacement sans armure","+9 m"]]}],"feats":{"Défense sans armure":"Dès le niveau 1, tant que vous ne portez ni armure ni bouclier, votre CA est égale à 10 + votre modificateur de Dextérité + votre modificateur de Sagesse.","Arts martiaux":"Au niveau 1, votre pratique des arts martiaux vous permet de maîtriser divers styles de combat à mains nues ou qui mettent en avant les armes de moine, à savoir l’épée courte et toutes les armes courantes de corps à corps qui n’ont pas la propriété à deux mains ni lourde.\nTant que vous combattez à mains nues ou avec des armes de moine et que vous ne portez ni armure ni bouclier, vous recevez les bénéfices suivants \n- Vous pouvez recourir à la Dextérité au lieu de la Force pour les jets d’attaque et de dégâts si vous attaquez à mains nues ou avec des armes de moine.\n- Vous pouvez lancer un d4 à la place des dégâts normaux de votre attaque à mains nues ou de votre arme de moine. Ce dé évolue à mesure que vous gagnez des niveaux de moine, comme indiqué dans la colonne « Arts martiaux » de la table « Le moine ».\n- Lorsque vous entreprenez l’action Attaquer à votre tour en frappant à mains nues ou avec une arme de moine, vous pouvez par une action bonus effectuer une attaque à mains nues supplémentaire. Si, par exemple, vous effectuez l’action Attaquer et attaquez avec un bâton de combat, vous pouvez également effectuer une attaque à mains nues par une action bonus, à supposer bien sûr que vous n’ayez pas déjà effectué d’action bonus ce tour-ci.\nCertains monastères utilisent des versions particulières des armes de moine. L’une d’elles est un bâton double articulé au moyen d’une courte chaîne, appelé nunchaku, une autre est une faucille à lame plus courte et plus droite, baptisée kama. Quel que soit le nom que vous donnez à une arme de moine, vous pouvez reprendre le profil de base de cette arme.","Le Ki":"À partir du niveau 2, votre entraînement vous permet de recourir à l’énergie mystique du ki. L’accès à ce type d’énergie est figuré par un certain nombre de points de ki. Votre niveau de moine détermine le nombre de points dont vous disposez, comme indiqué dans la colonne « Points de ki » de la table « Le moine ».\nVous pouvez dépenser ces points pour alimenter diverses aptitudes ki. Vous débutez en connaissant trois de ces aptitudes : Défense patiente, Déluge de coups et Porté par le vent. Vous apprenez davantage d’aptitudes ki à mesure que vous gagnez des niveaux dans cette classe.\nQuand vous dépensez un point de ki, il n’est plus disponible tant que vous n’avez pas terminé un repos court ou long, au terme duquel vous regagnez tout le quota dépensé. Vous devez consacrer au moins 30 minutes de ce repos à méditer pour récupérer vos points de ki.\nCertaines aptitudes ki contraignent votre cible à effectuer un jet de sauvegarde pour résister à un effet. Le DD des jets de sauvegarde est calculé comme suit :\nDD de sauvegarde contre le ki = 8 + votre bonus de maîtrise + votre modificateur de Sagesse","Déluge de coups":"Immédiatement après avoir entrepris l’action Attaquer à votre tour, vous pouvez dépenser 1 point de ki pour effectuer deux frappes à mains nues par une action bonus.","Défense patiente":"Vous pouvez dépenser 1 point de ki pour entreprendre l’action Esquiver à votre tour par une action bonus.","Porté par le vent":"Vous pouvez dépenser 1 point de ki pour entreprendre l’action Se désengager ou Foncer à votre tour par une action bonus, et votre distance de saut est doublée pendant ce tour.","Déplacement sans armure":"À partir du niveau 2, votre vitesse augmente de 3 m tant que vous ne portez ni armure ni bouclier. Ce bonus évolue à mesure que vous gagnez des niveaux de moine, comme indiqué dans la table « Le moine ».\nAu niveau 9, vous recevez la capacité de vous déplacer à votre tour le long de surfaces verticales et à travers des liquides sans tomber pendant ce déplacement.","Tradition monastique":"Lorsque vous atteignez le niveau 3, vous vous engagez dans une tradition monastique, telle que la Voie de la Paume. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6, 11 et 17.","Parade de projectiles":"À partir du niveau 3, vous pouvez jouer votre réaction pour dévier ou attraper un projectile lorsque vous êtes touché par une attaque d’arme à distance. Ce faisant, les dégâts que vous subissez de l’attaque sont réduits de 1d10 + votre modificateur de Dextérité + votre niveau de moine.\nSi vous en réduisez les dégâts à 0, vous pouvez attraper le projectile à condition d’avoir une main libre et que ses dimensions vous permettent de le tenir. Si vous attrapez ainsi un projectile, vous pouvez dans le cadre de la même réaction dépenser 1 point de ki pour effectuer une attaque à distance avec l’arme ou l’objet que vous venez de saisir. Vous effectuez cette attaque avec la maîtrise, que vous maîtrisiez ou non l’arme adverse, et le projectile est considéré comme une arme de moine pour cette attaque, avec une portée normale de 6 m et une portée longue de 18 m.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Chute ralentie":"À partir du niveau 4, vous pouvez jouer votre réaction pour réduire les dégâts de chute que vous subissez d’un montant égal à cinq fois votre niveau de moine.","Attaque supplémentaire":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.","Frappe étourdissante":"À partir du niveau 5, vous pouvez interférer avec le flux du ki dans le corps d’un adversaire. Lorsque vous touchez une autre créature avec une attaque d’arme de corps à corps, vous pouvez dépenser 1 point de ki pour tenter un coup étourdissant. La cible doit réussir un jet de sauvegarde de Constitution sous peine d’être étourdie jusqu’à la fin de votre tour suivant.","Frappes de ki":"À partir du niveau 6, vos frappes à mains nues sont considérées comme magiques pour ce qui est de surmonter la résistance et l’immunité contre les attaques et les dégâts non magiques.","Amélioration de tradition monastique":"Lorsque vous atteignez le niveau 3, vous vous engagez dans une tradition monastique, telle que la Voie de la Paume. Ce choix vous octroie des aptitudes au niveau 3, puis aux niveaux 6, 11 et 17.","Esquive totale":"Au niveau 7, votre agilité instinctive vous permet d’esquiver certains effets de zone, comme le souffle de foudre d’un dragon bleu ou le sort boule de feu. Quand vous êtes soumis à un effet qui vous permet d’effectuer un jet de sauvegarde de Dextérité pour réduire les dégâts de moitié, vous ne subissez aucun dégât en cas de sauvegarde réussie, et seulement la moitié en cas d’échec.","Sérénité":"À partir du niveau 7, vous pouvez consacrer votre action à mettre fin à un effet qui vous inflige l’état charmé ou effrayé.","Unarmored Movement":"À partir du niveau 2, votre vitesse augmente de 3 m tant que vous ne portez ni armure ni bouclier. Ce bonus évolue à mesure que vous gagnez des niveaux de moine, comme indiqué dans la table « Le moine ».\nAu niveau 9, vous recevez la capacité de vous déplacer à votre tour le long de surfaces verticales et à travers des liquides sans tomber pendant ce déplacement.","Pureté physique":"Au niveau 10, la maîtrise du ki qui circule en vous est telle que vous devenez immunisé contre les maladies et les poisons.","Langage du soleil et de la lune":"À partir du niveau 13, vous apprenez à entrer en contact avec le ki des autres esprits et comprenez toutes les langues parlées. De plus, toute créature qui comprend une langue saisit ce que vous dites.","Âme de diamant":"À partir du niveau 14, votre parfaite maîtrise du ki vous octroie la maîtrise de tous les jets de sauvegarde.\nEn outre, chaque fois que vous ratez un jet de sauvegarde, vous pouvez dépenser 1 point de ki pour le rejouer et prendre en compte le second résultat.","Jeunesse éternelle":"Au niveau 15, votre ki vous évite de souffrir des désagréments dus au grand âge, à tel point qu’aucune magie ne peut plus vous faire vieillir. Cela étant, vous pouvez toujours mourir de vieillesse. Enfin, vous pouvez vous passer de nourriture et d’eau.","Désertion de l’âme":"À partir du niveau 18, vous pouvez consacrer votre action et dépenser 4 points de ki pour devenir invisible pendant 1 minute. Vous bénéficiez pendant ce temps de la résistance à tous les dégâts sauf les dégâts de force.\nVous pouvez en outre dépenser 8 points de ki pour lancer le sort projection astrale sans ses composantes matérielles. Ce faisant, vous ne pouvez pas emmener d’autre créature avec vous.","Perfection de l’être":"Au niveau 20, quand vous jouez l’initiative alors qu’il ne vous reste plus aucun point de ki, vous en regagnez 4."},"subs":{"Voie de la paume":[[3,"Technique de la Paume","À partir du moment où vous choisissez cette tradition au niveau 3, vous pouvez manipuler le ki de l’adversaire à l’aide du vôtre. Chaque fois que vous touchez une créature avec l’une des attaques octroyées par votre Déluge de coups, vous pouvez imposer l’un des effets suivants à cette cible :\n- Elle doit réussir un jet de sauvegarde de Dextérité sous peine de se retrouver à terre.\n- Elle effectue un jet de sauvegarde de Force. Si elle échoue, vous pouvez la repousser jusqu’à 4,50 m de vous.\n- Elle ne peut pas jouer de réaction jusqu’à la fin de votre tour suivant."],[6,"Plénitude physique","Au niveau 6, vous apprenez à vous guérir. Au prix d’une action, vous pouvez regagner un total de points de vie égal à trois fois votre niveau de moine. Une fois que vous avez utilisé cette aptitude, vous devez terminer un repos long pour pouvoir y recourir de nouveau."],[11,"Ataraxie","À partir du niveau 11, vous pouvez entrer dans une méditation spéciale qui vous baigne d’une aura de paix. À la fin d’un repos long, vous bénéficiez de l’effet du sort sanctuaire qui dure jusqu’au début de votre prochain repos long (ce sort peut se terminer prématurément, comme de coutume). Le DD de sauvegarde contre ce sort est égal à 8 + votre modificateur de Sagesse + votre bonus de maîtrise."],[17,"Paume vibratoire","Au niveau 17, vous apprenez à produire des vibrations potentiellement mortelles dans le corps d’autrui. Lorsque vous touchez une créature avec une attaque à mains nues, vous pouvez dépenser 3 points de ki pour déclencher ces vibrations imperceptibles, qui durent un nombre de jours égal à votre niveau de moine. Ces vibrations sont inoffensives jusqu’à ce que vous consacriez votre action à y mettre fin. Pour ce faire, vous et la cible devez vous trouver sur le même plan d’existence. Quand vous accomplissez cette action, la créature effectue un jet de sauvegarde de Constitution. Si elle échoue, elle tombe à 0 point de vie. En cas de réussite, elle subit 10d10 dégâts nécrotiques.\nVous ne pouvez avoir qu’une créature à la fois sous l’effet de cette aptitude. Vous pouvez choisir de mettre fin aux vibrations de façon inoffensive sans dépenser d’action."]],"Voie de l'ombre":[[3,"Arts des ombres","2 ki : Ténèbres, Vision dans le noir, Passage sans trace ou Silence. Tu connais Illusion mineure."],[6,"Foulée d'ombre","En action bonus, téléportation de 18 m d'une zone sombre à une autre, avantage à ta prochaine attaque au contact."],[11,"Linceul d'ombre","Dans la pénombre ou les ténèbres, tu deviens invisible par une action."],[17,"Opportuniste","En réaction, tu attaques une créature à 1,5 m quand un allié la touche."]],"Voie des quatre éléments":[[3,"Disciple des éléments","Tu apprends des disciplines élémentaires qui coûtent du ki (Poing de l'air, Frappe de cendres, Poing des quatre tonnerres…). Une nouvelle aux niveaux 6, 11 et 17."]]}},"paladin":{"tab":[{"pb":2,"f":["Perception divine","Imposition des mains"],"x":[]},{"pb":2,"f":["Style de combat","Sorts : Paladin","Châtiment divin"],"x":[]},{"pb":2,"f":["Santé divine","Serment sacré","Sorts de serment","Conduit divin"],"x":[]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[]},{"pb":3,"f":["Attaque supplémentaire"],"x":[]},{"pb":3,"f":["Aura de protection"],"x":[["Auras","3 m"]]},{"pb":3,"f":["Amélioration de serment sacré"],"x":[["Auras","3 m"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Auras","3 m"]]},{"pb":4,"f":[],"x":[["Auras","3 m"]]},{"pb":4,"f":["Aura de courage"],"x":[["Auras","3 m"]]},{"pb":4,"f":["Châtiment divin amélioré"],"x":[["Auras","3 m"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Auras","3 m"]]},{"pb":5,"f":[],"x":[["Auras","3 m"]]},{"pb":5,"f":["Contact purificateur"],"x":[["Auras","3 m"]]},{"pb":5,"f":["Amélioration de serment sacré"],"x":[["Auras","3 m"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Auras","3 m"]]},{"pb":6,"f":[],"x":[["Auras","3 m"]]},{"pb":6,"f":["Auras améliorées"],"x":[["Auras","9 m"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Auras","9 m"]]},{"pb":6,"f":["Amélioration de serment sacré"],"x":[["Auras","9 m"]]}],"feats":{"Perception divine":"Vous ressentez la présence du mal comme une odeur nauséabonde, tandis qu’un bien puissant résonne à vos oreilles comme une musique céleste. Au prix d’une action, vous pouvez ouvrir votre conscience à de telles forces. Jusqu’à la fin de votre tour suivant, vous connaissez la position de tout céleste, fiélon et mort-vivant qui ne bénéficie pas d’un abri total, dans un rayon de 18 m. Vous apprenez le type de toute créature ainsi perçue (céleste, fiélon, mort-vivant), mais pas son identité (celle du vampire et comte Strahd von Zarovich, par exemple). Dans le même rayon, vous détectez également la présence de tout lieu ou objet qui a été consacré ou profané, comme avec le sort sanctification.\nVous pouvez recourir à cette aptitude un nombre de fois égal à 1 + votre modificateur de Charisme. Vous récupérez ce quota en terminant un repos long.","Imposition des mains":"Votre contact béni peut soigner les blessures. Vous disposez d’une réserve de puissance curatrice qui se reconstitue lorsque vous prenez un repos long. Cette réserve vous permet de faire regagner un total de points de vie égal à votre niveau de paladin x 5.\nAu prix d’une action, vous pouvez puiser tout ou partie de cette réserve et, d’un simple contact, faire récupérer autant de points de vie à une créature.\nAu lieu de cela, vous pouvez dépenser 5 points de vie de la réserve pour soigner la cible d’une maladie ou neutraliser un poison qui l’affecte. Vous pouvez soigner plusieurs maladies ou neutraliser plusieurs poisons d’une seule Imposition des mains, à condition d’acquitter les 5 points de vie pour chacun de ces maux.\nCette aptitude est sans effet sur les morts-vivants et les artificiels.","Style de combat":"Au niveau 2, vous décidez de vous spécialiser dans un style de combat particulier. Choisissez l’une des options suivantes. Vous ne pouvez pas opter plus d’une fois pour un même Style de combat, si vous avez de nouveau la possibilité d’en choisir un.\n\n• Style de combat : Défense : Tant que vous portez une armure, vous recevez un bonus de +1 en CA.\n\n• Style de combat : Duel : Lorsque vous maniez une arme de corps à corps dans une main et aucune autre arme, vous recevez un bonus de +2 aux jets de dégâts de cette arme.\n\n• Style de combat : Armes à deux mains : Lorsque vous obtenez un 1 ou un 2 sur un dé de dégâts d’une attaque effectuée avec une arme de corps à corps que vous tenez à deux mains, vous pouvez relancer ce dé, auquel cas c’est le nouveau jet qui s’applique. Pour que vous puissiez recevoir ce bénéfice, l’arme doit afficher la propriété « deux mains » ou « polyvalente ».\n\n• Style de combat : Protection : Lorsqu’une créature que vous voyez attaque une cible autre que vous située dans un rayon de 1,50 m de vous, vous pouvez jouer votre réaction pour lui imposer le désavantage au jet d’attaque. Vous devez porter un bouclier.","Sorts : Paladin":"Parvenu au niveau 2, vous avez appris à puiser dans la magie divine à force de méditation et de prières et lancez des sorts à la façon d’un clerc.","Châtiment divin":"À partir du niveau 2, lorsque vous touchez une créature avec une attaque d’arme au corps à corps, vous pouvez dépenser un emplacement de sort pour infliger des dégâts radiants à la cible en plus des dégâts de l’arme. Les dégâts supplémentaires sont de 2d8 pour un emplacement de sort de 1er niveau, plus 1d8 pour chaque niveau au-delà du 1er, jusqu’à un maximum de 5d8. Ces dégâts supplémentaires augmentent de 1d8 si la cible est un mort-vivant ou un fiélon.","Santé divine":"À partir du niveau 3, la magie divine qui vous parcourt vous immunise contre les maladies.","Serment sacré":"Parvenu au niveau 3, vous prêtez le serment qui vous lie pour toujours en tant que paladin. Jusqu’à ce stade, vous étiez en phase préparatoire, engagé sur la voie, mais pas encore sous serment. Il vous faut à présent choisir une voie, par exemple le Serment de Dévotion.\nCe choix vous octroie des aptitudes au niveau 3 puis aux niveaux 7, 15 et 20. Ces aptitudes incluent les sorts de serment et l’aptitude Conduit divin.","Sorts de serment":"Chaque serment est associé à une liste de sorts. Vous accédez à ces sorts aux niveaux spécifiés dans la description du serment. Une fois que vous avez accédé à un sort de serment, celui-ci est toujours préparé. Les sorts de serment ne sont pas décomptés du nombre de sorts que vous pouvez préparer quotidiennement.\nSi vous disposez d’un sort de serment qui n’apparaît pas dans la liste des sorts de paladin, il n’en est pas moins considéré comme un sort de paladin dans votre cas.","Conduit divin":"Votre serment vous permet de canaliser l’énergie divine afin de générer des effets magiques. Chaque option de Conduit divin fournie par votre serment détaille comment l’utiliser.\nLorsque vous recourez à votre Conduit divin, vous choisissez quelle option appliquer. Vous devez terminer un repos court ou long pour pouvoir réutiliser votre Conduit divin.\nCertains effets de Conduit divin entraînent des jets de sauvegarde. Lorsque vous recourez à un tel effet par cette classe, le DD correspondant est égal à votre DD de sauvegarde des sorts de paladin.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Attaque supplémentaire":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.","Aura de protection":"À partir du niveau 6, chaque fois que vous-même ou une créature amicale dans un rayon de 3 m de vous effectuez un jet de sauvegarde, cette créature reçoit un bonus au jet de sauvegarde égal à votre modificateur de Charisme (bonus minimum de +1).\nVous devez être conscient pour octroyer ce bonus. Au niveau 18, la portée de cette aura passe à 9 m.","Amélioration de serment sacré":"Parvenu au niveau 3, vous prêtez le serment qui vous lie pour toujours en tant que paladin. Jusqu’à ce stade, vous étiez en phase préparatoire, engagé sur la voie, mais pas encore sous serment. Il vous faut à présent choisir une voie, par exemple le Serment de Dévotion.\nCe choix vous octroie des aptitudes au niveau 3 puis aux niveaux 7, 15 et 20. Ces aptitudes incluent les sorts de serment et l’aptitude Conduit divin.","Aura de courage":"À partir du niveau 10, vous-même et les créatures amicales dans un rayon de 3 m de vous ne pouvez plus subir l’état effrayé tant que vous êtes conscient.\nAu niveau 18, la portée de cette aura passe à 9 m.","Châtiment divin amélioré":"Au niveau 11, vous débordez d’une telle puissance vertueuse que toutes vos attaques d’arme de corps à corps sont imprégnées de puissance divine. Chaque fois que vous touchez une créature avec une arme de corps à corps, elle subit 1d8 dégâts radiants supplémentaires. Si vous utilisez également votre Châtiment divin lors d’une attaque, ces dégâts s’ajoutent aux dégâts supplémentaires du Châtiment divin.","Contact purificateur":"À partir du niveau 14, vous pouvez consacrer votre action à mettre fin à un sort sur vous-même ou sur une créature consentante que vous touchez.\nVous pouvez recourir à cette aptitude autant de fois que votre modificateur de Charisme (minimum une fois). Vous récupérez ce quota en terminant un repos long.","Auras améliorées":"Au niveau 18, la portée de vos auras passe à 9 m."},"subs":{"Serment de dévotion":[[3,"Conduit divin : Arme sacrée","Au prix d’une action qui utilise votre Conduit divin, vous arborez votre symbole sacré pour imprégner d’énergie positive une arme que vous tenez. Pendant 1 minute, vous ajoutez votre modificateur de Charisme aux jets d’attaque effectués avec cette arme (avec un bonus minimum de +1). L’arme émet également une lumière vive dans un rayon de 6 m, et une lumière faible sur 6 m de plus. Si l’arme n’est pas déjà magique, elle le devient jusqu’à la fin des effets.\nVous pouvez mettre un terme à ces effets à votre tour, dans le cadre de n’importe quelle autre action. Ils prennent également fin dès que l’arme n’est plus sur vous ou que vous devenez inconscient."],[3,"Conduit divin : Renvoi des impies","Au prix d’une action qui utilise votre Conduit divin, vous arborez votre symbole sacré en prononçant une prière condamnant les fiélons et les morts-vivants. Tout fiélon ou mort-vivant qui vous voit ou vous entend dans un rayon de 9 m de vous effectue un jet de sauvegarde de Sagesse. Une créature qui échoue à ce jet de sauvegarde est renvoyée pendant 1 minute ou jusqu’à ce qu’elle subisse des dégâts.\nUne créature renvoyée doit consacrer ses tours de jeu à s’éloigner le plus possible de vous et ne peut volontairement se déplacer vers un espace situé à 9 m ou moins de vous. Elle ne peut en outre pas jouer de réaction. Comme action, elle ne peut entreprendre que Foncer ou tenter de se libérer d’un effet qui l’empêche de se déplacer. Si elle n’a nulle part où aller, elle peut entreprendre l’action Esquiver."],[7,"Aura de dévotion","À partir du niveau 7, vous-même et les créatures amicales dans un rayon de 3 m de vous ne pouvez plus subir l’état charmé tant que vous-même êtes conscient.\nAu niveau 18, la portée de cette aura passe à 9 m."],[15,"Pureté de l’esprit","À partir du niveau 15, vous êtes toujours sous l’effet du sort protection contre le mal et le bien."],[20,"Nimbe sacré","Au niveau 20 et au prix d’une action, il émane de vous une aura de lumière solaire. Pendant 1 minute, une lumière vive brille dans un rayon de 9 m de vous, et une lumière faible sur 9 m de plus.\nChaque fois qu’une créature ennemie commence son tour dans la lumière vive, elle subit 10 dégâts radiants.\nEn outre et pour toute la durée de cette aptitude, vous êtes avantagé aux jets de sauvegarde contre les sorts lancés par les fiélons et les morts-vivants.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos long pour pouvoir y recourir de nouveau."]],"Serment des anciens":[[3,"Conduit divin : courroux de la nature","Des lianes entravent une créature à 3 m (jet de Force ou Dextérité chaque tour). Sorts de serment : communication avec les animaux, frappe piégeuse, foulée brumeuse, rayon de lune, croissance végétale, protection contre une énergie, peau de pierre, tempête de grêle, communion avec la nature, passage par les arbres."],[3,"Conduit divin : renvoi des infidèles","Fées et fiélons à 9 m font un jet de Sagesse ou fuient 1 minute."],[7,"Aura de garde","Toi et tes alliés à 3 m (9 m au niveau 18) résistez aux dégâts des sorts."],[15,"Sentinelle immortelle","Une fois par repos long, à 0 PV, tu restes à 1 PV."],[20,"Champion antique","1 minute : régénération 10 PV par tour, sorts en action bonus, désavantage aux sauvegardes des ennemis proches."]],"Serment de vengeance":[[3,"Conduit divin : conspuer l'ennemi","Une créature à 18 m fait un jet de Sagesse ou est effrayée 1 minute ; sinon sa vitesse est divisée par deux. Sorts de serment : fléau, marque du chasseur, foulée brumeuse, immobilisation de personne, hâte, protection contre une énergie, bannissement, porte dimensionnelle, immobilisation de monstre, scrutation."],[3,"Conduit divin : vœu d'hostilité","En action bonus, avantage à tes attaques contre une créature à 3 m pendant 1 minute."],[7,"Vengeur implacable","Après une attaque d'opportunité réussie, tu te déplaces de la moitié de ta vitesse sans provoquer."],[15,"Âme vengeresse","En réaction, tu attaques la cible de ton vœu quand elle attaque."],[20,"Ange de la vengeance","1 heure : ailes (vol 18 m) et aura de peur de 9 m."]]}},"rodeur":{"tab":[{"pb":2,"f":["Ennemi juré (1 ennemi)","Explorateur-né (1 type d'environnement)"],"x":[["Ennemis jurés",1],["Environnements de prédilection",1]]},{"pb":2,"f":["Style de combat","Sorts : Ranger"],"x":[["Ennemis jurés",1],["Environnements de prédilection",1]]},{"pb":2,"f":["Archétype de rôdeur","Vigilance primitive"],"x":[["Ennemis jurés",1],["Environnements de prédilection",1]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Ennemis jurés",1],["Environnements de prédilection",1]]},{"pb":3,"f":["Attaque supplémentaire"],"x":[["Ennemis jurés",1],["Environnements de prédilection",1]]},{"pb":3,"f":["Ennemi juré (2 ennemis)","Explorateur-né (2 types d'environnement)"],"x":[["Ennemis jurés",2],["Environnements de prédilection",2]]},{"pb":3,"f":["Amélioration d’archétype de rôdeur"],"x":[["Ennemis jurés",2],["Environnements de prédilection",2]]},{"pb":3,"f":["Amélioration de caractéristique","Foulée tellurique"],"x":[["Ennemis jurés",2],["Environnements de prédilection",2]]},{"pb":4,"f":[],"x":[["Ennemis jurés",2],["Environnements de prédilection",2]]},{"pb":4,"f":["Explorateur-né (3 types d'environnement)","Camouflage naturel"],"x":[["Ennemis jurés",2],["Environnements de prédilection",3]]},{"pb":4,"f":["Amélioration d’archétype de rôdeur"],"x":[["Ennemis jurés",2],["Environnements de prédilection",3]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Ennemis jurés",2],["Environnements de prédilection",3]]},{"pb":5,"f":[],"x":[["Ennemis jurés",2],["Environnements de prédilection",3]]},{"pb":5,"f":["Ennemi juré (3 ennemis)","Disparition"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":5,"f":["Amélioration d’archétype de rôdeur"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":6,"f":[],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":6,"f":["Sens sauvages"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]},{"pb":6,"f":["Tueur implacable"],"x":[["Ennemis jurés",3],["Environnements de prédilection",3]]}],"feats":{"Ennemi juré (1 ennemi)":"Dès le niveau 1, vous possédez une expérience significative dans l’étude, la traque, la chasse et même le dialogue avec un certain type d’ennemi.\nChoisissez un type d’ennemi juré parmi : aberrations, artificiels, bêtes, célestes, dragons, élémentaires, fées, fiélons, géants, monstruosités, morts-vivants, plantes et vases. Alternativement, vous pouvez désigner comme ennemis jurés deux races d’humanoïdes, par exemple les gnolls et les orcs.\nVous êtes avantagé aux tests de Sagesse (Survie) visant à suivre à la trace vos ennemis jurés ainsi qu’aux tests d’Intelligence destinés à vous remémorer des informations les concernant.\nQuand vous recevez cette aptitude, vous apprenez en outre une langue de votre choix parlée par vos ennemis jurés, s’ils en parlent une.\nVous choisissez un ennemi juré supplémentaire, ainsi qu’une langue associée, aux niveaux 6 et 14. Ces choix sont censés refléter les types de monstres que vous avez combattus au fil de vos aventures.","Explorateur-né (1 type d'environnement)":"Particulièrement à l’aise dans un type d’environnement naturel, vous êtes tout à fait apte à voyager et à survivre dans de telles régions. Choisissez un type de terrain favori parmi arctique, désert, forêt, littoral, marais, montagne ou plaine. Lorsque vous effectuez un test d’Intelligence ou de Sagesse lié à votre terrain de prédilection, votre bonus de maîtrise est doublé si vous recourez à une compétence que vous maîtrisez.\nLors des voyages d’une heure ou plus sur votre terrain de prédilection, vous recevez les bénéfices suivants :\n- Le terrain difficile ne ralentit pas les déplacements de votre groupe.\n- Seules des mesures magiques peuvent égarer votre groupe.\n- Même lorsque vous êtes engagé dans une autre activité pendant le voyage, comme la recherche de nourriture, la navigation ou le pistage, vous restez attentif au danger.\n- Si vous voyagez seul, vous pouvez vous déplacer furtivement à allure normale.\n- Lorsque vous cherchez à manger et à boire, vous trouvez deux fois plus de nourriture que vous ne le feriez normalement.\n- Tout en pistant d’autres créatures, vous apprenez également leur effectif précis, leur taille et depuis combien de temps elles sont passées dans la zone.\nVous choisissez un type de terrain de prédilection supplémentaire aux niveaux 6 et 10.","Style de combat":"Au niveau 2, vous décidez de vous spécialiser dans un style de combat particulier. Choisissez l’une des options suivantes. Vous ne pouvez pas opter plus d’une fois pour un même Style de combat, si vous avez de nouveau la possibilité d’en choisir un.\n\n• Style de combat : Archerie : Vous recevez un bonus de +2 aux jets d’attaque effectués avec des armes à distance.\n\n• Style de combat : Défense : Tant que vous portez une armure, vous recevez un bonus de +1 en CA.\n\n• Style de combat : Duel : Lorsque vous maniez une arme de corps à corps dans une main et aucune autre arme, vous recevez un bonus de +2 aux jets de dégâts de cette arme.\n\n• Style de combat : Combat à deux armes : Lorsque vous combattez avec deux armes, vous pouvez ajouter votre modificateur de caractéristique aux dégâts de la seconde attaque.","Sorts : Ranger":"Quand vous atteignez le niveau 2, vous avez appris à utiliser l’essence magique de la nature pour lancer des sorts, à la façon d’un druide.","Archétype de rôdeur":"Au niveau 3, vous choisissez l’archétype qui va vous servir de modèle, comme celui du Chasseur. Ce choix vous octroie des aptitudes au niveau 3 puis aux niveaux 7, 11 et 15.","Vigilance primitive":"À partir du niveau 3, vous pouvez consacrer votre action et dépenser un emplacement de sort de rôdeur afin de concentrer votre attention sur la région environnante. Pendant 1 minute par niveau de l’emplacement de sort ainsi dépensé, vous percevez si les types de créature suivants sont présents dans un rayon de 1,5 km autour de vous (ou dans un rayon de 9 km sur votre terrain de prédilection) : aberrations, célestes, dragons, élémentaires, fées, fiélons et morts-vivants. Cette aptitude ne révèle ni l’emplacement ni l’effectif de ces créatures.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Attaque supplémentaire":"À partir du niveau 5, vous pouvez attaquer deux fois au lieu d’une seule lorsque vous entreprenez l’action Attaquer à votre tour.","Ennemi juré (2 ennemis)":"Dès le niveau 1, vous possédez une expérience significative dans l’étude, la traque, la chasse et même le dialogue avec un certain type d’ennemi.\nChoisissez un type d’ennemi juré parmi : aberrations, artificiels, bêtes, célestes, dragons, élémentaires, fées, fiélons, géants, monstruosités, morts-vivants, plantes et vases. Alternativement, vous pouvez désigner comme ennemis jurés deux races d’humanoïdes, par exemple les gnolls et les orcs.\nVous êtes avantagé aux tests de Sagesse (Survie) visant à suivre à la trace vos ennemis jurés ainsi qu’aux tests d’Intelligence destinés à vous remémorer des informations les concernant.\nQuand vous recevez cette aptitude, vous apprenez en outre une langue de votre choix parlée par vos ennemis jurés, s’ils en parlent une.\nVous choisissez un ennemi juré supplémentaire, ainsi qu’une langue associée, aux niveaux 6 et 14. Ces choix sont censés refléter les types de monstres que vous avez combattus au fil de vos aventures.","Explorateur-né (2 types d'environnement)":"Particulièrement à l’aise dans un type d’environnement naturel, vous êtes tout à fait apte à voyager et à survivre dans de telles régions. Choisissez un type de terrain favori parmi arctique, désert, forêt, littoral, marais, montagne ou plaine. Lorsque vous effectuez un test d’Intelligence ou de Sagesse lié à votre terrain de prédilection, votre bonus de maîtrise est doublé si vous recourez à une compétence que vous maîtrisez.\nLors des voyages d’une heure ou plus sur votre terrain de prédilection, vous recevez les bénéfices suivants :\n- Le terrain difficile ne ralentit pas les déplacements de votre groupe.\n- Seules des mesures magiques peuvent égarer votre groupe.\n- Même lorsque vous êtes engagé dans une autre activité pendant le voyage, comme la recherche de nourriture, la navigation ou le pistage, vous restez attentif au danger.\n- Si vous voyagez seul, vous pouvez vous déplacer furtivement à allure normale.\n- Lorsque vous cherchez à manger et à boire, vous trouvez deux fois plus de nourriture que vous ne le feriez normalement.\n- Tout en pistant d’autres créatures, vous apprenez également leur effectif précis, leur taille et depuis combien de temps elles sont passées dans la zone.\nVous choisissez un type de terrain de prédilection supplémentaire aux niveaux 6 et 10.","Amélioration d’archétype de rôdeur":"Au niveau 3, vous choisissez l’archétype qui va vous servir de modèle, comme celui du Chasseur. Ce choix vous octroie des aptitudes au niveau 3 puis aux niveaux 7, 11 et 15.","Foulée tellurique":"À partir du niveau 8, vous déplacer sur un terrain difficile non magique ne vous coûte aucun déplacement supplémentaire. Vous pouvez également traverser la végétation non magique sans être ralenti par elle ni subir de dégâts si elle possède des épines, des aiguilles ou tout autre danger similaire.\nVous êtes en outre avantagé aux jets de sauvegarde contre les plantes créées ou manipulées magiquement afin d’empêcher le déplacement, comme celles créées par le sort enchevêtrement","Explorateur-né (3 types d'environnement)":"Particulièrement à l’aise dans un type d’environnement naturel, vous êtes tout à fait apte à voyager et à survivre dans de telles régions. Choisissez un type de terrain favori parmi arctique, désert, forêt, littoral, marais, montagne ou plaine. Lorsque vous effectuez un test d’Intelligence ou de Sagesse lié à votre terrain de prédilection, votre bonus de maîtrise est doublé si vous recourez à une compétence que vous maîtrisez.\nLors des voyages d’une heure ou plus sur votre terrain de prédilection, vous recevez les bénéfices suivants :\n- Le terrain difficile ne ralentit pas les déplacements de votre groupe.\n- Seules des mesures magiques peuvent égarer votre groupe.\n- Même lorsque vous êtes engagé dans une autre activité pendant le voyage, comme la recherche de nourriture, la navigation ou le pistage, vous restez attentif au danger.\n- Si vous voyagez seul, vous pouvez vous déplacer furtivement à allure normale.\n- Lorsque vous cherchez à manger et à boire, vous trouvez deux fois plus de nourriture que vous ne le feriez normalement.\n- Tout en pistant d’autres créatures, vous apprenez également leur effectif précis, leur taille et depuis combien de temps elles sont passées dans la zone.\nVous choisissez un type de terrain de prédilection supplémentaire aux niveaux 6 et 10.","Camouflage naturel":"À partir du niveau 10, vous pouvez consacrer 1 minute à vous créer un camouflage. Vous devez avoir accès à de la boue fraîche, de la terre, des plantes, de la suie et tout autre matériau naturel permettant de créer un tel camouflage.\nUne fois camouflé de cette manière, vous pouvez essayer de vous cacher en vous plaquant contre une surface pleine, de type tronc d’arbre ou paroi, à condition qu’elle soit au moins aussi haute et large que vous. Vous recevez un bonus de +10 aux tests de Dextérité (Discrétion) tant que vous restez sans bouger ni entreprendre d’action. Dès que vous vous déplacez, entreprenez une action ou jouez une réaction, vous devez vous camoufler de nouveau pour bénéficier de cette aptitude.","Ennemi juré (3 ennemis)":"Dès le niveau 1, vous possédez une expérience significative dans l’étude, la traque, la chasse et même le dialogue avec un certain type d’ennemi.\nChoisissez un type d’ennemi juré parmi : aberrations, artificiels, bêtes, célestes, dragons, élémentaires, fées, fiélons, géants, monstruosités, morts-vivants, plantes et vases. Alternativement, vous pouvez désigner comme ennemis jurés deux races d’humanoïdes, par exemple les gnolls et les orcs.\nVous êtes avantagé aux tests de Sagesse (Survie) visant à suivre à la trace vos ennemis jurés ainsi qu’aux tests d’Intelligence destinés à vous remémorer des informations les concernant.\nQuand vous recevez cette aptitude, vous apprenez en outre une langue de votre choix parlée par vos ennemis jurés, s’ils en parlent une.\nVous choisissez un ennemi juré supplémentaire, ainsi qu’une langue associée, aux niveaux 6 et 14. Ces choix sont censés refléter les types de monstres que vous avez combattus au fil de vos aventures.","Disparition":"À partir du niveau 14, vous pouvez effectuer l’action Se cacher par une action bonus. En outre, vous ne pouvez pas être pisté par des moyens non magiques, sauf si vous décidez sciemment de laisser une trace.","Sens sauvages":"Au niveau 18, vous développez des sens surnaturels qui vous aident à combattre les créatures que vous ne voyez pas. Lorsque vous attaquez une créature que vous ne voyez pas, cela ne vous impose pas le désavantage à vos jets d’attaque contre elle.\nVous avez en outre connaissance de la position de toutes les créatures invisibles dans un rayon de 9 m autour de vous, à la condition que ces créatures ne vous soient pas cachées et que vous ne soyez ni aveuglé ni assourdi.","Tueur implacable":"Au niveau 20, vous avez développé un talent exceptionnel dans l’art de la chasse aux ennemis. Une fois à chacun de vos tours, vous pouvez ajouter votre modificateur de Sagesse au jet d’attaque ou au jet de dégâts d’une attaque effectuée contre l’un de vos ennemis jurés. Vous pouvez choisir de recourir à cette aptitude avant ou après le jet, mais avant que les effets du jet ne soient appliqués."},"subs":{"Chasseur":[[3,"Proie du chasseur","Au niveau 3, vous recevez l’une des aptitudes suivantes de votre choix.\nGoût du sang\nTueur de géants\nBriseur de hordes\n\n• Proie du chasseur : Goût du sang : Votre ténacité vient à bout des ennemis les plus puissants. Quand vous touchez une créature avec une attaque d’arme, celle-ci subit 1d8 dégâts supplémentaires si elle est en dessous de son maximum de points de vie. Vous ne pouvez infliger ces dégâts supplémentaires qu’une fois par tour.\n\n• Proie du chasseur : Tueur de géants : Lorsqu’une créature de taille G ou supérieure située dans un rayon de 1,50 m vous touche ou vous rate avec une attaque, vous pouvez jouer votre réaction pour l’attaquer immédiatement après cette attaque, à condition de voir la créature.\n\n• Proie du chasseur : Briseur de hordes : Une fois à chacun de vos tours, lorsque vous effectuez une attaque d’arme, vous pouvez effectuer une autre attaque avec la même arme contre une créature différente située dans un rayon de 1,50 m de la cible d’origine et à portée de votre arme."],[7,"Tactiques défensives","Au niveau 7, vous recevez l’une des aptitudes suivantes de votre choix.\nCauchemar de la horde\nDéfense contre les attaques multiples\nMoral d’acier\n\n• Tactiques défensives : Cauchemar de la horde : Les attaques d’opportunité qui vous visent se font avec désavantage.\n\n• Tactiques défensives : Défense contre les attaques multiples : Lorsqu’une créature vous touche avec une attaque, vous recevez un bonus de +4 à la CA contre toutes les attaques ultérieures effectuées par cette créature pour le reste du tour.\n\n• Tactiques défensives : Moral d’acier : Vous êtes avantagé aux jets de sauvegarde contre l’état effrayé."],[11,"Attaques multiples","Au niveau 11, vous recevez l’une des aptitudes suivantes de votre choix.\nVolée\nAttaque tourbillonnante\n\n• Attaques multiples : Volée : Vous pouvez consacrer votre action à effectuer une attaque à distance contre autant de créatures que vous voulez dans un rayon de 3 m d’un point que vous voyez à portée de votre arme. Vous devez disposer d’un projectile pour chaque cible et vous effectuez un jet d’attaque distinct pour chaque cible.\n\n• Attaques multiples : Attaque tourbillonnante : Vous pouvez consacrer votre action à effectuer une attaque de corps à corps contre autant de créatures que vous voulez dans un rayon de 1,50 m de vous, en effectuant un jet d’attaque distinct pour chaque cible."],[15,"Défense de chasseur supérieure","Au niveau 15, vous recevez l’une des aptitudes suivantes de votre choix.\nEsquive totale\nRetour de bâton\nEsquive instinctive\n\n• Défense de chasseur supérieure : Esquive totale : Quand vous êtes soumis à un effet (le souffle ardent d’un dragon rouge ou le sort éclair, par exemple) qui vous permet d’effectuer un jet de sauvegarde de Dextérité pour réduire les dégâts de moitié, vous ne subissez aucun dégât en cas de sauvegarde réussie, et seulement la moitié en cas d’échec.\n\n• Défense de chasseur supérieure : Retour de bâton : Quand une créature hostile vous rate avec une attaque de corps à corps, vous pouvez jouer votre réaction pour la contraindre à réitérer la même attaque contre une autre créature (autre qu’elle-même) de votre choix.\n\n• Défense de chasseur supérieure : Esquive instinctive : Lorsqu’un assaillant que vous voyez vous touche avec une attaque, vous pouvez jouer votre réaction pour réduire de moitié les dégâts de cette attaque."]],"Maître des bêtes":[[3,"Compagnon du rôdeur","Un animal compagnon (taille M max, FP 1/4) qui ajoute ton bonus de maîtrise et obéit à tes ordres."],[7,"Entraînement exceptionnel","En action bonus, ton compagnon peut Aider, Foncer, Se désengager ou Esquiver ; ses attaques sont magiques."],[11,"Fureur bestiale","Ton compagnon attaque deux fois."],[15,"Partage des sorts","Un sort qui te vise peut aussi affecter ton compagnon à 9 m."]],"Gardien de drake":[[3,"Compagnon drake","Tu invoques un drake qui agit après toi (morsure + dégâts d'un élément). Tu connais Thaumaturgie et le draconique."],[7,"Lien du croc et d'écailles","Le drake devient de taille M et peut voler ; sa morsure inflige plus de dégâts ; tu résistes à son élément."],[11,"Souffle de drake","Par une action, cône de 9 m : jet de Dextérité, 8d6 dégâts (moitié si réussi)."],[15,"Lien parfait","Le drake devient Grand, sa morsure s'améliore ; en réaction, il accorde une résistance."]]}},"roublard":{"tab":[{"pb":2,"f":["Expertise","Attaque sournoise","Argot des voleurs"],"x":[["Attaque sournoise","1d6"]]},{"pb":2,"f":["Ruse"],"x":[["Attaque sournoise","1d6"]]},{"pb":2,"f":["Archétype de roublard"],"x":[["Attaque sournoise","2d6"]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","2d6"]]},{"pb":3,"f":["Esquive instinctive"],"x":[["Attaque sournoise","3d6"]]},{"pb":3,"f":["Expertise"],"x":[["Attaque sournoise","3d6"]]},{"pb":3,"f":["Esquive totale"],"x":[["Attaque sournoise","4d6"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","4d6"]]},{"pb":4,"f":["Amélioration d’archétype de roublard"],"x":[["Attaque sournoise","5d6"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","5d6"]]},{"pb":4,"f":["Savoir-faire"],"x":[["Attaque sournoise","6d6"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","6d6"]]},{"pb":5,"f":["Amélioration d’archétype de roublard"],"x":[["Attaque sournoise","7d6"]]},{"pb":5,"f":["Perception aveugle"],"x":[["Attaque sournoise","7d6"]]},{"pb":5,"f":["Esprit fuyant"],"x":[["Attaque sournoise","8d6"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","8d6"]]},{"pb":6,"f":["Amélioration d’archétype de roublard"],"x":[["Attaque sournoise","9d6"]]},{"pb":6,"f":["Insaisissable"],"x":[["Attaque sournoise","9d6"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Attaque sournoise","10d6"]]},{"pb":6,"f":["Coup de chance"],"x":[["Attaque sournoise","10d6"]]}],"feats":{"Expertise":"Au niveau 1, choisissez deux de vos maîtrises de compétence ou une maîtrise de compétence et la maîtrise des outils de voleur. Votre bonus de maîtrise est doublé pour tous vos tests de caractéristique associés à l’une ou l’autre des maîtrises choisies.\nAu niveau 6, vous pouvez appliquer ce bénéfice à deux autres de vos maîtrises (de compétence ou d’outils de voleur).","Attaque sournoise":"À partir du niveau 1, vous savez porter des attaques qui exploitent subtilement les baisses d’attention de l’adversaire. Une fois par tour, vous pouvez infliger 1d6 dégâts supplémentaires à une créature que vous touchez avec une attaque pour laquelle vous êtes avantagé. L’attaque doit se faire avec une arme à distance ou dotée de la propriété finesse.\nVous n’êtes pas tenu d’être avantagé au jet d’attaque si un autre ennemi non neutralisé de la cible se situe dans un rayon de 1,50 m d’elle et si vous n’êtes pas désavantagé au jet d’attaque.\nLes dégâts supplémentaires augmentent au fil de votre progression dans cette classe, comme le montre la colonne « Attaque sournoise » de la table « Le roublard ».","Argot des voleurs":"Durant votre formation, vous avez appris l’argot des voleurs, mélange secret de divers dialectes, jargons et codes vous permettant de glisser des messages cachés dans des conversations qui semblent anodines. Seule une créature maîtrisant l’argot des voleurs peut saisir ces messages. Communiquer des informations par ce biais demande quatre fois plus de temps que si vous énonciez clairement la même idée.\nPar ailleurs, vous connaissez un ensemble de signes et symboles secrets permettant de transmettre des messages brefs et simples, comme indiquer la dangerosité d’une zone, marquer le territoire d’une guilde de voleurs, annoncer la proximité d’un butin, renseigner sur la crédulité de la population locale ou sur sa propension à héberger des filous en cavale.","Ruse":"À partir du niveau 2, votre esprit vif et votre agilité vous permettent d’agir et de filer promptement. Vous avez droit à une action bonus à chacun de vos tours de combat. Elle ne peut servir qu’à entreprendre l’action Foncer, Se cacher ou Se désengager.","Archétype de roublard":"Au niveau 3, vous choisissez un archétype, sorte d’idéal que vous tentez de reproduire dans l’expression de vos talents de roublard, comme le Voleur. Ce choix d’archétype vous octroie des aptitudes au niveau 3 puis aux niveaux 9, 13 et 17.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 10, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Esquive instinctive":"À partir du niveau 5, lorsqu’un assaillant que vous voyez vous touche avec une attaque, vous pouvez jouer votre réaction pour réduire les dégâts correspondants de moitié (uniquement sur vous).","Esquive totale":"Au niveau 7, votre agilité instinctive vous permet d’esquiver certains effets de zone, comme le souffle ardent d’un dragon rouge ou le sort tempête de grêle. Quand vous êtes soumis à un effet qui vous permet d’effectuer un jet de sauvegarde de Dextérité pour réduire les dégâts de moitié, vous ne subissez aucun dégât en cas de sauvegarde réussie, et seulement la moitié en cas d’échec.","Amélioration d’archétype de roublard":"Au niveau 3, vous choisissez un archétype, sorte d’idéal que vous tentez de reproduire dans l’expression de vos talents de roublard, comme le Voleur. Ce choix d’archétype vous octroie des aptitudes au niveau 3 puis aux niveaux 9, 13 et 17.","Savoir-faire":"Au niveau 11, vous êtes arrivé à un haut degré de perfection dans vos compétences de prédilection. Chaque fois que vous effectuez un test de caractéristique qui vous permet d’ajouter votre bonus de maîtrise, vous pouvez considérer tout jet de 9 ou moins sur le d20 comme un 10.","Perception aveugle":"À partir du niveau 14 et à condition de pouvoir entendre, vous connaissez la position exacte de toute créature cachée ou invisible dans un rayon de 3 m.","Esprit fuyant":"Parvenu au niveau 15, vous avez acquis une grande force mentale. Vous recevez la maîtrise des jets de sauvegarde de Sagesse.","Insaisissable":"À partir du niveau 18, vous êtes tellement agile que vos agresseurs ont rarement le dessus sur vous. Aucun jet d’attaque n’est avantagé contre vous tant que vous n’êtes pas neutralisé.","Coup de chance":"Au niveau 20, vous avez développé un don surnaturel pour réussir quand l’enjeu est crucial. Si votre attaque rate une cible à portée, vous pouvez transformer cet échec en réussite. Par ailleurs, si vous ratez un test de caractéristique, vous pouvez transformer le résultat du d20 en 20.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos court ou long pour pouvoir y recourir de nouveau."},"subs":{"Voleur":[[3,"Mains lestes","À partir du niveau 3, vous pouvez consacrer l’action bonus octroyée par votre Ruse à effectuer un test de Dextérité (Escamotage), à utiliser vos outils de voleur pour désarmer un piège ou crocheter une serrure ou à entreprendre l’action Utiliser un objet."],[3,"Monte-en-l’air","Lorsque vous optez pour cet archétype au niveau 3, vous recevez la capacité de grimper plus vite que la normale, si bien que l’escalade ne vous coûte plus de déplacement supplémentaire.\nPar ailleurs, lorsque vous effectuez un saut avec élan, la distance couverte augmente de 30 cm par point de modificateur de Dextérité."],[9,"Furtivité suprême","À partir du niveau 9, vous êtes avantagé à vos tests de Dextérité (Discrétion) si vous ne vous déplacez pas de plus de la moitié de votre vitesse pendant ce tour."],[13,"Utilisation d’objets magiques","Au niveau 13, vous en savez assez sur le fonction- nement de la magie pour pouvoir improviser l’utilisation d’objets qui ne vous sont pas destinés. Vous ne tenez pas compte des contraintes de classe, de race et de niveau lorsqu’il s’agit d’utiliser un objet magique."],[17,"Réflexes de voleur","Parvenu au niveau 17, vous avez peaufiné l’art de tendre une embuscade et d’échapper rapidement au danger. Vous pouvez jouer deux tours lors du premier round de chaque combat. Vous jouez votre premier tour à votre rang d’initiative normal et votre deuxième tour à ce même rang moins 10. Vous ne pouvez pas recourir à cette aptitude si vous êtes surpris."]],"Assassin":[[3,"Assassinat","Maîtrise des kits de déguisement et d'empoisonneur. Avantage contre une créature qui n'a pas encore agi ; un coup sur une créature surprise est critique."],[9,"Expert en infiltration","Tu te crées de fausses identités."],[13,"Imposteur","Tu imites parfaitement voix, écriture et manières."],[17,"Frappe meurtrière","Sur une créature surprise : jet de Constitution ou dégâts doublés."]],"Escroc arcanique":[[3,"Incantation","Sorts de magicien (enchantement et illusion surtout), caractéristique : Intelligence."],[3,"Escamotage et main de mage","Ta main de mage est invisible et peut voler, crocheter ou désarmer un piège."],[9,"Embuscade magique","Si tu es caché, la cible a un désavantage à sa sauvegarde contre ton sort."],[13,"Escroc polyvalent","En action bonus, ta main de mage distrait une créature : avantage à tes attaques contre elle."],[17,"Voleur de sort","En réaction, tu voles un sort qui te vise (jet de l'incantateur)."]],"Conspirateur":[[3,"Maître des intrigues et des tactiques","Kits de déguisement et de contrefaçon, deux langues ; l'action Aider en action bonus, à 9 m."],[9,"Manipulateur perspicace","Après 1 minute d'observation, tu compares une créature à toi."],[13,"Redirection","En réaction, une attaque qui te visait touche une créature qui te sert d'abri."],[17,"Âme de trompeur","Pensées protégées et mensonges indétectables par la magie."]]}},"ensorceleur":{"tab":[{"pb":2,"f":["Sorts : Ensorceleur","Origine magique"],"x":[]},{"pb":2,"f":["Réserve arcanique","Magie modulable : Création d’emplacements de sort","Magie modulable : Convertir un emplacement de sort en points de sorcellerie"],"x":[["Points de sorcellerie",2]]},{"pb":2,"f":["Métamagie"],"x":[["Points de sorcellerie",3],["Options de métamagie",2]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Points de sorcellerie",4],["Options de métamagie",2]]},{"pb":3,"f":[],"x":[["Points de sorcellerie",5],["Options de métamagie",2]]},{"pb":3,"f":["Amélioration d’origine magique"],"x":[["Points de sorcellerie",6],["Options de métamagie",2]]},{"pb":3,"f":[],"x":[["Points de sorcellerie",7],["Options de métamagie",2]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Points de sorcellerie",8],["Options de métamagie",2]]},{"pb":4,"f":[],"x":[["Points de sorcellerie",9],["Options de métamagie",2]]},{"pb":4,"f":["Métamagie"],"x":[["Points de sorcellerie",10],["Options de métamagie",3]]},{"pb":4,"f":[],"x":[["Points de sorcellerie",11],["Options de métamagie",3]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Points de sorcellerie",12],["Options de métamagie",3]]},{"pb":5,"f":[],"x":[["Points de sorcellerie",13],["Options de métamagie",3]]},{"pb":5,"f":["Amélioration d’origine magique"],"x":[["Points de sorcellerie",14],["Options de métamagie",3]]},{"pb":5,"f":[],"x":[["Points de sorcellerie",15],["Options de métamagie",3]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Points de sorcellerie",16],["Options de métamagie",4]]},{"pb":6,"f":["Métamagie"],"x":[["Points de sorcellerie",17],["Options de métamagie",4]]},{"pb":6,"f":["Amélioration d’origine magique"],"x":[["Points de sorcellerie",18],["Options de métamagie",4]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Points de sorcellerie",19],["Options de métamagie",4]]},{"pb":6,"f":["Restauration ensorcelée"],"x":[["Points de sorcellerie",20],["Options de métamagie",4]]}],"feats":{"Sorts : Ensorceleur":"Un événement de votre passé, ou de celui d’un parent ou ancêtre, a laissé une marque indélébile sur vous et vous permet de piocher dans la magie profane. C’est cette source de magie, quelle que soit son origine, qui alimente vos sorts.","Origine magique":"Choisissez une origine magique, qui décrit la source de votre pouvoir magique inné, comme Lignée draconique.\nCe choix vous octroie des aptitudes dès le niveau 1 puis de nouveau aux niveaux 6, 14 et 18.","Réserve arcanique":"Dès le niveau 2, vous savez puiser dans le puits sans fond de magie qui se cache en vous-même. Cette source est figurée par des points de sorcellerie, qui vous permettent de créer une variété d’effets magiques.\nPoints de sorcellerie\nVous disposez de 2 points de sorcellerie et en recevez davantage à mesure que vous atteignez des niveaux plus élevés, comme indiqué dans la colonne « Points de sorcellerie » de la table « L’ensorceleur ». Vous n’aurez jamais plus de points de sorcellerie que ce qui est indiqué sur la table à votre niveau. Vous récupérez tous les points de sorcellerie dépensés en terminant un repos long.","Magie modulable : Création d’emplacements de sort":"À votre tour, vous pouvez par une action bonus transformer des points de sorcellerie non dépensés en un emplacement de sort. La table « Création d’emplacements de sort » indique le coût de création d’un emplacement de sort selon son niveau. Vous ne pouvez pas créer d’emplacements de sort d’un niveau supérieur au 5e.\nTout emplacement de sort créé avec cette aptitude disparaît quand vous terminez un repos long.","Magie modulable : Convertir un emplacement de sort en points de sorcellerie":"À votre tour, vous pouvez par une action bonus dépenser un emplacement de sort pour recevoir un nombre de points de sorcellerie égal au niveau de cet emplacement.","Métamagie":"Au niveau 3, vous apprenez à façonner les sorts que vous lancez. Vous choisissez deux des options de métamagie ci-après. Vous en recevez une autre aux niveaux 10 et 17.\nVous ne pouvez appliquer qu’une option de métamagie à l’incantation d’un sort, sauf si cette option précise le contraire.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Amélioration d’origine magique":"Choisissez une origine magique, qui décrit la source de votre pouvoir magique inné, comme Lignée draconique.\nCe choix vous octroie des aptitudes dès le niveau 1 puis de nouveau aux niveaux 6, 14 et 18.","Restauration ensorcelée":"Au niveau 20, vous regagnez 4 points de sorcellerie dépensés chaque fois que vous terminez un repos court."},"subs":{"Lignée draconique":[[1,"Ancêtre draconique","Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite.\nVous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Noir - Dégâts d’acide : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Bleu - Dégâts de foudre : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Airain - Dégâts de feu : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Bronze - Dégâts de foudre : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Cuivre - Dégâts d’acide : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Or - Dégâts de feu : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Vert - Dégâts de poison : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Rouge - Dégâts de feu : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Argent - Dégâts de froid : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé.\n\n• Ascendance draconique : Blanc - Dégâts de froid : Au niveau 1, vous choisissez un type de dragon comme ancêtre. Le type de dégâts associé à chaque dragon est utilisé par les aptitudes que vous recevrez par la suite. Vous parlez, lisez et écrivez le draconique. En outre, chaque fois que vous effectuez un test de Charisme lorsque vous interagissez avec des dragons et que votre bonus de maîtrise est censé s’appliquer, ce bonus est doublé."],[1,"Résistance draconique","À mesure que la magie circule dans votre corps, elle fait émerger les traits physiques de vos ancêtres dragons. Au niveau 1, votre maximum de points de vie augmente de 1, et augmente encore de 1 chaque fois que vous gagnez un niveau dans cette classe.\nDe plus, certaines parties de votre corps sont couvertes de fines écailles rappelant celles des dragons. Tant que vous ne portez pas d’armure, votre CA est égale à 13 + votre modificateur de Dextérité."],[6,"Affinité élémentaire","À partir du niveau 6, lorsque vous lancez un sort qui inflige des dégâts du type associé à votre ascendance draconique, vous pouvez ajouter votre modificateur de Charisme à un jet de dégâts de ce sort. En parallèle, vous pouvez dépenser 1 point de sorcellerie pour recevoir la résistance à ce type de dégâts pendant 1 heure."],[14,"Ailes draconiques","Au niveau 14, vous recevez la capacité de faire pousser deux ailes de dragon dans votre dos, acquérant une vitesse de vol égale à votre vitesse actuelle. À votre tour, vous pouvez créer ces ailes par une action bonus. Elles persistent jusqu’à ce que vous les révoquiez à votre tour par une action bonus.\nVous ne pouvez pas faire pousser ces ailes en portant une armure à moins que celle-ci ait été conçue sur mesure, et les vêtements qui ne sont pas taillés pour accueillir vos ailes risquent d’être détruits lorsque vous les déployez."],[18,"Présence draconique","À partir du niveau 18, vous pouvez canaliser la présence redoutable de votre ancêtre dragon, suscitant l’émerveillement ou l’effroi chez ceux qui vous entourent. Au prix d’une action, vous pouvez dépenser 5 points de sorcellerie pour puiser dans ce pouvoir et dégager une aura d’émerveillement ou de terreur (au choix) dans un rayon de 18 m. Pendant 1 minute ou jusqu’à ce que vous perdiez votre concentration (comme pour un sort), chaque créature hostile qui commence son tour dans cette aura doit réussir un jet de sauvegarde de Sagesse sous peine de subir l’état charmé (si vous avez choisi l’émerveillement) ou effrayé (si vous avez choisi la terreur) jusqu’à ce que l’aura cesse. Une créature qui réussit ce jet de sauvegarde est immunisée contre votre aura pendant 24 heures."]],"Magie sauvage":[[1,"Pic de magie sauvage","Après un sort de niveau 1+, le MJ peut te faire lancer 1d20 : sur un 1, effet aléatoire de la table de magie sauvage."],[1,"Marée du chaos","Avantage à un jet ; se recharge après un repos long ou un pic de magie sauvage."],[6,"Chance forcée","En réaction, 2 points de sorcellerie pour ajouter ou retirer 1d4 au jet d'une créature visible."],[14,"Chaos contrôlé","Sur la table de magie sauvage, lance deux fois et choisis."],[18,"Bombardement de sort","Une fois par tour, un dé de dégâts au maximum est relancé et ajouté."]]}},"occultiste":{"tab":[{"pb":2,"f":["Protecteur d’outre-monde","Magie de pacte"],"x":[]},{"pb":2,"f":["Manifestations occultes"],"x":[["Manifestations occultes",2]]},{"pb":2,"f":["Pacte"],"x":[["Manifestations occultes",2]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Manifestations occultes",3]]},{"pb":3,"f":[],"x":[["Manifestations occultes",3]]},{"pb":3,"f":["Amélioration de protecteur d’outre-monde"],"x":[["Manifestations occultes",4]]},{"pb":3,"f":[],"x":[["Manifestations occultes",4]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Manifestations occultes",4]]},{"pb":4,"f":[],"x":[["Manifestations occultes",5]]},{"pb":4,"f":["Amélioration de protecteur d’outre-monde"],"x":[["Manifestations occultes",5]]},{"pb":4,"f":["Arcanum mystique (sorts niveau 6)"],"x":[["Manifestations occultes",5],["Arcanum mystique","niv. 6"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Manifestations occultes",6],["Arcanum mystique","niv. 6"]]},{"pb":5,"f":["Arcanum mystique (sorts niveau 7)"],"x":[["Manifestations occultes",6],["Arcanum mystique","niv. 6, 7"]]},{"pb":5,"f":["Amélioration de protecteur d’outre-monde"],"x":[["Manifestations occultes",6],["Arcanum mystique","niv. 6, 7"]]},{"pb":5,"f":["Arcanum mystique (sorts niveau 8)"],"x":[["Manifestations occultes",7],["Arcanum mystique","niv. 6, 7, 8"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Manifestations occultes",7],["Arcanum mystique","niv. 6, 7, 8"]]},{"pb":6,"f":["Arcanum mystique (sorts niveau 9)"],"x":[["Manifestations occultes",7],["Arcanum mystique","niv. 6, 7, 8, 9"]]},{"pb":6,"f":[],"x":[["Manifestations occultes",8],["Arcanum mystique","niv. 6, 7, 8, 9"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Manifestations occultes",8],["Arcanum mystique","niv. 6, 7, 8, 9"]]},{"pb":6,"f":["Maître de l’occulte"],"x":[["Manifestations occultes",8],["Arcanum mystique","niv. 6, 7, 8, 9"]]}],"feats":{"Protecteur d’outre-monde":"Au niveau 1, vous avez conclu un pacte avec une entité d’outre-monde de votre choix : l’Archifée, le Fiélon ou le Grand Ancien. Seul le Fiélon est détaillé à la fin de la description de cette classe. Ce choix vous octroie des aptitudes au niveau 1 puis de nouveau aux niveaux 6, 10 et 14.","Magie de pacte":"Vos recherches ésotériques ainsi que la magie dont vous a fait don votre protecteur vous octroient la faculté de lancer des sorts.","Manifestations occultes":"Vos études sur la science de l’obscur vous ont permis d’exhumer des manifestations occultes, fragments de savoir interdit qui vous donnent accès à des pouvoirs magiques.\nAu niveau 2, vous recevez deux manifestations occultes de votre choix. Les options disponibles sont détaillées en fin de description de la classe. Vous en apprendrez d’autres que vous choisirez à plus haut niveau, comme le montre la colonne « Manifestations connues » de la table « L’occultiste ».\nPar ailleurs, lorsque vous gagnez un niveau dans cette classe, vous pouvez choisir l’une des manifestations occultes que vous connaissez pour la remplacer par une manifestation tirée de celles que vous pouvez recevoir à ce niveau.\n\n• Manifestations occultes : Décharge déchirante : Quand vous lancez décharge occulte, vous ajoutez votre modificateur de Charisme aux dégâts qu’elle inflige quand elle touche.\n\n• Manifestations occultes : Armure d’ombres : Vous pouvez lancer armure du mage sur vous-même à volonté, sans dépenser d’emplacement de sort ni de composantes matérielles.\n\n• Manifestations occultes : Langage animal : Vous pouvez lancer communication avec les animaux à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Présence captivante : Vous recevez la maîtrise des compétences Persuasion et Tromperie.\n\n• Manifestations occultes : Livre des secrets anciens : Vous pouvez désormais inscrire des rituels magiques dans votre Codex des Ombres. Choisissez deux sorts du 1er niveau portant la mention « rituel » dans la liste de sorts de n’importe quelle classe (les deux n’appartiennent pas nécessairement à la même liste). Les sorts qui figurent dans le codex ne sont pas décomptés de vos sorts connus. Votre Codex des Ombres en main, vous pouvez lancer les sorts choisis comme rituels. Vous ne pouvez lancer ces sorts que comme rituels, à moins que vous ne les ayez appris par d’autres biais. Vous pouvez aussi lancer comme rituel un sort d’occultiste que vous connaissez si ce sort porte la mention « rituel ». Au fil de vos aventures, vous pouvez ajouter d’autres sorts de rituel à votre Codex des Ombres. Lorsque vous trouvez un tel sort, vous pouvez l’ajouter au livre à condition que le niveau du sort soit inférieur ou égal à la moitié de votre niveau d’occultiste (arrondi au supérieur) et que vous preniez le temps de retranscrire ce sort. Cette opération nécessite 2 heures et 50 po par niveau du sort en raison des encres rares nécessaires à sa recopie.\n\n• Manifestations occultes : Vision du diable : Vous voyez normalement dans les ténèbres magiques et ordinaires, dans un rayon de 36 m.\n\n• Manifestations occultes : Vision occulte : Vous pouvez lancer détection de la magie à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Lance occulte : Lorsque vous lancez décharge occulte, sa portée est de 90 m.\n\n• Manifestations occultes : Œil du gardien des runes : Vous pouvez lire tous les écrits.\n\n• Manifestations occultes : Vigueur fiélonne : Vous pouvez lancer simulacre de vie sur vous-même à volonté en tant que sort du 1er niveau, sans dépenser d’emplacement de sort ni de composantes matérielles.\n\n• Manifestations occultes : Perception transférée : Vous pouvez consacrer votre action à entrer en contact avec un humanoïde consentant afin de percevoir à travers ses sens jusqu’à la fin de votre tour suivant. Lors des tours suivants et tant que cette créature se trouve sur le même plan d’existence que vous, vous pouvez consacrer votre action à maintenir cette connexion sensorielle, ce qui prolonge la durée de l’effet jusqu’à la fin de votre tour suivant. Tout en percevant à travers les sens de l’autre créature, vous bénéficiez de tous les sens spéciaux qu’elle possède et vous êtes aveuglé et assourdi vis-à-vis de votre propre environnement.\n\n• Manifestations occultes : Mille visages : Vous pouvez lancer déguisement à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Visions embrumées : Vous pouvez lancer image silencieuse à volonté, sans dépenser d’emplacement de sort ni de composantes matérielles.\n\n• Manifestations occultes : Décharge répulsive : Quand vous touchez une créature avec décharge occulte, vous pouvez la repousser en ligne droite d’un maximum de 3 m.\n\n• Manifestations occultes : Voleur des cinq destinées : Vous pouvez lancer imprécation une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Voix du maître des chaînes : Vous pouvez communiquer par télépathie avec votre familier et percevoir à travers ses sens à condition de vous trouver sur le même plan d’existence. De plus, tout en percevant à travers les sens de votre familier, vous pouvez parler à voix haute par la bouche de celui-ci, même si votre familier est normalement incapable de parler.\n\n• Manifestations occultes : Avachissement : Vous pouvez lancer lenteur une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Maître des ombres : Quand vous vous trouvez dans une zone de lumière faible ou de ténèbres, vous pouvez consacrer votre action à devenir invisible jusqu’à ce que vous vous déplaciez, entrepreniez une action ou jouiez votre réaction.\n\n• Manifestations occultes : Sombre présage : Vous pouvez lancer malédiction une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Lame assoiffée : Vous pouvez attaquer deux fois au lieu d’une avec votre arme de pacte lorsque vous entreprenez l’action Attaquer à votre tour.\n\n• Manifestations occultes : Murmures impérieux : Vous pouvez lancer compulsion une fois sans dépenser d’emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Mot d’effroi : Vous pouvez lancer confusion une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Sculpteur de chair : Vous pouvez lancer métamorphose une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Pas aérien : Vous pouvez lancer lévitation sur vous-même à volonté, sans dépenser d’emplacement de sort ni de composantes matérielles.\n\n• Manifestations occultes : Sbires du chaos : Vous pouvez lancer invocation d’élémentaire une fois en dépensant un emplacement de sort d’occultiste. Vous devez terminer un repos long avant de pouvoir le relancer ainsi.\n\n• Manifestations occultes : Saut d’outre-monde : Vous pouvez lancer saut sur vous-même à volonté, sans dépenser d’emplaceme.\n\n• Manifestations occultes : Murmures de la tombe : Vous pouvez lancer communication avec les morts à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Buveuse de vie : Lorsque vous touchez une créature avec votre arme de pacte, cette créature subit des dégâts nécrotiques supplémentaires égaux à votre modificateur de Charisme (minimum 1).\n\n• Manifestations occultes : Chaînes des Carcères : Vous pouvez lancer immobilisation de monstre à volonté si la cible est un céleste, un fiélon ou un élémentaire, sans dépenser d’emplacement de sort ni de composantes matérielles. Vous devez terminer un repos long avant de pouvoir réutiliser cette manifestation sur une même créature.\n\n• Manifestations occultes : Maître des formes : Vous pouvez lancer modification d’apparence à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Royaumes lointains : Vous pouvez lancer œil du mage à volonté, sans dépenser d’emplacement de sort.\n\n• Manifestations occultes : Vision sorcière : Vous discernez la forme véritable des métamorphes ou des créatures dissimulées derrière une magie d’illusion ou de transmutation dans un rayon de 9 m, à condition qu’ils soient dans votre champ de vision.","Pacte":"Au niveau 3, votre protecteur d’outre-monde vous octroie une faveur pour services rendus. Vous recevez l’une des aptitudes suivantes au choix.\n\n• Pacte de la chaîne : Vous apprenez le sort appel de familier que vous pouvez lancer comme rituel. Ce sort n’est pas décompté de vos sorts connus. À l’incantation du sort, vous pouvez choisir l’une des formes normales pour votre familier ou l’une des formes spéciales suivantes : diablotin, esprit follet, pseudodragon ou quasit. En outre, lorsque vous entreprenez l’action Attaquer, vous pouvez renoncer à l’une de vos attaques pour permettre à votre familier d’effectuer l’une de ses attaques en jouant sa réaction.\n\n• Pacte de la lame : Vous pouvez consacrer votre action à créer une arme de pacte dans votre main vide. Vous pouvez choisir la forme que prend cette arme de corps à corps chaque fois que vous la créez. Vous en avez la maîtrise tant que vous la portez. Cette arme est considérée comme magique pour ce qui est de surmonter la résistance et l’immunité contre les attaques et les dégâts non magiques Votre arme de pacte disparaît si elle se retrouve à plus de 1,50 m de vous pendant 1 minute ou plus. Elle disparaît également si vous recourez de nouveau à cette aptitude, si vous révoquez l’arme (pas d’action requise) ou si vous mourez. Vous pouvez transformer une arme magique en votre arme de pacte en accomplissant un rituel spécial tout en tenant cette arme. Ce rituel dure 1 heure et peut être accompli pendant un repos court. Vous pouvez ensuite révoquer l’arme qui disparaît dans un espace extradimensionnel, pour réapparaître chaque fois que vous créez votre arme de pacte par la suite. Vous ne pouvez pas affecter un artefact ou une arme intelligente de cette manière. L’arme cesse d’être votre arme de pacte si vous mourez, si vous effectuez le même rituel d’une heure sur une arme différente ou si vous accomplissez un rituel d’une heure pour rompre votre lien avec elle. L’arme apparaît à vos pieds si elle se trouve dans l’espace extradimensionnel lorsque le lien se rompt.\n\n• Pacte du grimoire : Votre protecteur vous fait don d’un grimoire appelé Codex des Ombres. Quand vous recevez cette aptitude, choisissez trois sorts mineurs dans la liste de sorts de n’importe quelle classe (les trois n’appartiennent pas nécessairement à la même liste). Tant que vous portez ce codex sur vous, vous pouvez lancer ces sorts mineurs à volonté. Ils ne sont pas décomptés de vos sorts mineurs connus. S’ils n’apparaissent pas dans la liste des sorts d’occultiste, ce sont malgré tout des sorts d’occultiste en ce qui vous concerne. Si vous perdez votre Codex des Ombres, vous pouvez accomplir une cérémonie d’une heure pour recevoir un nouvel exemplaire de la part de votre protecteur. La cérémonie peut s’accomplir pendant un repos court ou long et détruit le codex précédent. Le livre est réduit en cendres si vous mourez.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Amélioration de protecteur d’outre-monde":"Au niveau 1, vous avez conclu un pacte avec une entité d’outre-monde de votre choix : l’Archifée, le Fiélon ou le Grand Ancien. Seul le Fiélon est détaillé à la fin de la description de cette classe. Ce choix vous octroie des aptitudes au niveau 1 puis de nouveau aux niveaux 6, 10 et 14.","Arcanum mystique (sorts niveau 6)":"Au niveau 11, votre protecteur vous octroie un secret magique appelé arcanum. Choisissez comme arcanum un sort du 6e niveau dans la liste des sorts d’occultiste.\nVous pouvez lancer votre sort d’arcanum une fois sans dépenser d’emplacement de sort. Vous devez terminer un repos long pour pouvoir recourir de nouveau à cette aptitude.\nAux niveaux supérieurs, vous recevez d’autres sorts d’occultiste de votre choix qui peuvent être lancés de cette manière : un sort du 7e niveau au niveau 13, un sort du 8e niveau au niveau 15 et un sort du 9e niveau au niveau 17. Vous récupérez tous vos utilisations d’Arcanum mystique en terminant un repos long.","Arcanum mystique (sorts niveau 7)":"Au niveau 11, votre protecteur vous octroie un secret magique appelé arcanum. Choisissez comme arcanum un sort du 6e niveau dans la liste des sorts d’occultiste.\nVous pouvez lancer votre sort d’arcanum une fois sans dépenser d’emplacement de sort. Vous devez terminer un repos long pour pouvoir recourir de nouveau à cette aptitude.\nAux niveaux supérieurs, vous recevez d’autres sorts d’occultiste de votre choix qui peuvent être lancés de cette manière : un sort du 7e niveau au niveau 13, un sort du 8e niveau au niveau 15 et un sort du 9e niveau au niveau 17. Vous récupérez tous vos utilisations d’Arcanum mystique en terminant un repos long.","Arcanum mystique (sorts niveau 8)":"Au niveau 11, votre protecteur vous octroie un secret magique appelé arcanum. Choisissez comme arcanum un sort du 6e niveau dans la liste des sorts d’occultiste.\nVous pouvez lancer votre sort d’arcanum une fois sans dépenser d’emplacement de sort. Vous devez terminer un repos long pour pouvoir recourir de nouveau à cette aptitude.\nAux niveaux supérieurs, vous recevez d’autres sorts d’occultiste de votre choix qui peuvent être lancés de cette manière : un sort du 7e niveau au niveau 13, un sort du 8e niveau au niveau 15 et un sort du 9e niveau au niveau 17. Vous récupérez tous vos utilisations d’Arcanum mystique en terminant un repos long.","Arcanum mystique (sorts niveau 9)":"Au niveau 11, votre protecteur vous octroie un secret magique appelé arcanum. Choisissez comme arcanum un sort du 6e niveau dans la liste des sorts d’occultiste.\nVous pouvez lancer votre sort d’arcanum une fois sans dépenser d’emplacement de sort. Vous devez terminer un repos long pour pouvoir recourir de nouveau à cette aptitude.\nAux niveaux supérieurs, vous recevez d’autres sorts d’occultiste de votre choix qui peuvent être lancés de cette manière : un sort du 7e niveau au niveau 13, un sort du 8e niveau au niveau 15 et un sort du 9e niveau au niveau 17. Vous récupérez tous vos utilisations d’Arcanum mystique en terminant un repos long.","Maître de l’occulte":"Au niveau 20, vous pouvez piocher dans votre réserve intérieure de puissance mystique en implorant votre protecteur de vous rendre des emplacements de sort dépensés. Vous pouvez passer 1 minute à prier votre protecteur de vous rendre tous vos emplacements dépensés de l’aptitude Magie de pacte. Une fois vos emplacements récupérés de cette manière, vous devez terminer un repos long avant de pouvoir recourir à cette aptitude.\nOnce you regain spell slots with this feature, you must finish a long rest before you can do so again."},"subs":{"Fiélon":[[1,"Bénédiction du ténébreux","Dès le niveau 1, quand vous réduisez une créature hostile à 0 point de vie, vous recevez autant de points de vie temporaires que votre modificateur de Charisme + votre niveau d’occultiste (minimum 1)."],[6,"Chance du ténébreux","À partir du niveau 6, vous pouvez demander à votre protecteur qu’il modifie le destin en votre faveur. Lorsque vous effectuez un test de caractéristique ou un jet de sauvegarde, vous pouvez recourir à cette aptitude pour ajouter un d10 à ce jet. Vous pouvez le faire après avoir effectué le jet initial, mais avant qu’interviennent les effets du jet.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos court ou long pour pouvoir y recourir de nouveau."],[10,"Résistance fiélonne","À partir du niveau 10, vous pouvez choisir un type de dégâts quand vous terminez un repos court ou long. Vous recevez la résistance à ce type de dégâts jusqu’à ce que vous en choisissiez un autre avec cette aptitude. Les dégâts des armes magiques ou des armes en argent passent outre à cette résistance."],[14,"Traversée des enfers","À partir du niveau 14, lorsque vous touchez une créature avec une attaque, vous pouvez utiliser cette aptitude pour transporter instantanément la cible dans les Plans Inférieurs. La créature disparaît et traverse à vive allure un paysage de cauchemar.\nÀ la fin de votre tour suivant, la cible réapparaît dans l’espace qu’elle avait quitté ou dans l’espace inoccupé le plus proche s’il n’est plus libre. Si la cible n’est pas un fiélon, elle subit 10d10 dégâts psychiques dus au traumatisme de cette horrible expérience.\nUne fois que vous avez utilisé cette aptitude, vous devez terminer un repos long pour pouvoir y recourir de nouveau."]],"Archifée":[[1,"Présence féerique","Par une action, les créatures dans un cube de 3 m font un jet de Sagesse ou sont charmées ou effrayées jusqu'à la fin de ton prochain tour (une fois par repos court)."],[6,"Échappatoire brumeuse","En réaction à des dégâts, tu deviens invisible et te téléportes de 18 m (une fois par repos court)."],[10,"Défenses captivantes","Immunité au charme ; tu peux retourner un charme contre son auteur."],[14,"Sombre délire","Une créature est plongée dans une illusion, charmée ou effrayée 1 minute (une fois par repos court)."]],"Grand Ancien":[[1,"Esprit éveillé","Télépathie avec les créatures à 9 m."],[6,"Protection entropique","En réaction, désavantage à une attaque contre toi ; si elle rate, avantage à ta prochaine attaque contre l'attaquant."],[10,"Bouclier mental","Pensées protégées, résistance psychique et tu renvoies ces dégâts."],[14,"Asservissement","Tu charmes un humanoïde neutralisé."]],"Génie":[[1,"Catalyseur de génie","Un objet magique focaliseur : refuge extradimensionnel et +dégâts (bonus de maîtrise) une fois par tour, du type de ton génie."],[6,"Présent élémentaire","Résistance au type de ton génie et vol en action bonus."],[10,"Sanctuaire du génie","Jusqu'à cinq créatures dans ton catalyseur, qui y récupèrent comme lors d'un repos court."],[14,"Souhait limité","Tu lances un sort de niveau 6 ou moins (une fois tous les 1d4 repos longs)."]]}},"magicien":{"tab":[{"pb":2,"f":["Sorts : Wizard","Restauration magique"],"x":[["Restauration arcanique","1 niveaux"]]},{"pb":2,"f":["Tradition arcanique"],"x":[["Restauration arcanique","1 niveaux"]]},{"pb":2,"f":[],"x":[["Restauration arcanique","2 niveaux"]]},{"pb":2,"f":["Amélioration de caractéristique"],"x":[["Restauration arcanique","2 niveaux"]]},{"pb":3,"f":[],"x":[["Restauration arcanique","3 niveaux"]]},{"pb":3,"f":["Amélioration de tradition arcanique"],"x":[["Restauration arcanique","3 niveaux"]]},{"pb":3,"f":[],"x":[["Restauration arcanique","4 niveaux"]]},{"pb":3,"f":["Amélioration de caractéristique"],"x":[["Restauration arcanique","4 niveaux"]]},{"pb":4,"f":[],"x":[["Restauration arcanique","5 niveaux"]]},{"pb":4,"f":["Amélioration de tradition arcanique"],"x":[["Restauration arcanique","5 niveaux"]]},{"pb":4,"f":[],"x":[["Restauration arcanique","6 niveaux"]]},{"pb":4,"f":["Amélioration de caractéristique"],"x":[["Restauration arcanique","6 niveaux"]]},{"pb":5,"f":[],"x":[["Restauration arcanique","7 niveaux"]]},{"pb":5,"f":["Amélioration de tradition arcanique"],"x":[["Restauration arcanique","7 niveaux"]]},{"pb":5,"f":[],"x":[["Restauration arcanique","8 niveaux"]]},{"pb":5,"f":["Amélioration de caractéristique"],"x":[["Restauration arcanique","8 niveaux"]]},{"pb":6,"f":[],"x":[["Restauration arcanique","9 niveaux"]]},{"pb":6,"f":["Maîtrise des sorts"],"x":[["Restauration arcanique","9 niveaux"]]},{"pb":6,"f":["Amélioration de caractéristique"],"x":[["Restauration arcanique","10 niveaux"]]},{"pb":6,"f":["Sorts de prédilection"],"x":[["Restauration arcanique","10 niveaux"]]}],"feats":{"Sorts : Wizard":"Disciple de la magie arcanique, vous disposez d’un grimoire renfermant les sorts représentant les premières lueurs de votre véritable puissance.","Restauration magique":"Vous avez appris à récupérer une partie de votre énergie magique en étudiant votre grimoire. Une fois par jour quand vous terminez un repos court, vous pouvez désigner des emplacements de sort dépensés que vous souhaitez récupérer. La somme des niveaux de ces emplacements ne doit pas excéder la moitié de votre niveau de magicien (arrondie au supérieur), et aucun de ces emplacements de sort ne doit être du 6e niveau ou supérieur.\nExemple : si vous êtes une magicienne de niveau 4, vous pouvez récupérer jusqu’à deux niveaux d’emplacements de sort. Il peut s’agir d’un emplacement de sort du 2e niveau ou de deux emplacements du 1er niveau.","Tradition arcanique":"Lorsque vous atteignez le niveau 2, vous choisissez une tradition arcanique qui façonne votre pratique de la magie parmi les huit écoles de magie, comme Évocation.\nCe choix vous octroie des aptitudes au niveau 2, puis aux niveaux 6, 10 et 14.","Amélioration de caractéristique":"Lorsque vous atteignez le niveau 4 (puis à nouveau aux niveaux 8, 12, 16 et 19), vous pouvez augmenter de 2 la valeur de caractéristique de votre choix, ou augmenter de 1 deux valeurs de caractéristique de votre choix. Conformément à la règle habituelle, cette aptitude ne vous permet pas de porter une valeur au-delà de 20.","Amélioration de tradition arcanique":"Lorsque vous atteignez le niveau 2, vous choisissez une tradition arcanique qui façonne votre pratique de la magie parmi les huit écoles de magie, comme Évocation.\nCe choix vous octroie des aptitudes au niveau 2, puis aux niveaux 6, 10 et 14.","Maîtrise des sorts":"Au niveau 18, vous avez atteint une telle maîtrise de certains sorts que vous pouvez désormais les lancer à volonté. Choisissez un sort de magicien du 1er niveau et un sort de magicien du 2e niveau de votre grimoire. Quand ils sont préparés, vous pouvez lancer ces sorts à leur niveau le plus bas sans avoir à dépenser d’emplacement de sort. Si vous souhaitez les lancer à un niveau supérieur, vous devez toutefois dépenser un emplacement de sort.\nVous pouvez échanger l’un de ces sorts ou les deux contre des sorts du même niveau en y consacrant 8 heures d’étude.","Sorts de prédilection":"Arrivé au niveau 20, vous recevez la maîtrise de deux sorts puissants que vous pouvez lancer sans réel effort. Choisissez deux sorts de magicien du 3e niveau de votre grimoire comme sorts de prédilection. Ces sorts sont toujours considérés comme préparés, sans toutefois être décomptés des sorts que vous pouvez préparer. Vous pouvez lancer chacun d’eux une fois au 3e niveau sans avoir à dépenser d’emplacement de sort. Après cela, vous devez terminer un repos court ou long avant de pouvoir les relancer sans emplacement.\nSi vous souhaitez les lancer à un niveau supérieur, vous devez dépenser un emplacement de sort."},"subs":{"Évocation":[[2,"Évocateur érudit","Dès que vous sélectionnez cette école au niveau 2, vous réduisez de moitié les coûts en or et en temps de toute transcription de sort d’évocation dans votre grimoire."],[2,"Façonneur de sorts","À partir du niveau 2, vous pouvez créer des niches protectrices au sein des zones d’effet de vos sorts d’évocation. Lorsque vous lancez un sort d’évocation qui affecte d’autres créatures que vous voyez, vous pouvez en désigner un nombre n’excédant pas 1 + le niveau du sort. Les créatures choisies réussissent automatiquement leur jet de sauvegarde contre le sort et ne subissent aucun dégât si elles étaient censées les réduire de moitié en cas de sauvegarde réussie."],[6,"Sort mineur appuyé","À partir du niveau 6, vos sorts mineurs restent redoutables pour les créatures qui pensent s’y soustraire. Lorsqu’une créature réussit son jet de sauvegarde contre l’un de vos sorts mineurs, elle subit quand même la moitié des dégâts du sort, le cas échéant, sans toutefois être soumise aux autres effets éventuels du sort."],[10,"Évocation améliorée","À partir du niveau 10, vous pouvez ajouter votre modificateur d’Intelligence à un jet de dégâts de tout sort d’évocation de magicien que vous lancez."],[14,"Surcharge magique","À partir du niveau 14, vous pouvez augmenter la puissance de vos sorts les plus simples. Lorsque vous lancez un sort de magicien du 1er au 5e niveau qui inflige des dégâts, vous pouvez décider d’infliger le maximum des dégâts de ce sort.\nLa première fois que vous procédez ainsi, vous ne subissez aucun effet indésirable. Si vous recourez de nouveau à cette aptitude avant d’avoir terminé un repos long, vous subissez 2d12 dégâts nécrotiques pour chaque niveau du sort, immédiatement après l’avoir lancé. Chaque fois que vous réutilisez cette aptitude avant de terminer un repos long, les dégâts nécrotiques par niveau de sort augmentent de 1d12. Ces dégâts passent outre à la résistance et à l’immunité."]],"Abjuration":[[2,"Protection arcanique","Un sceau absorbe des dégâts (2 × niveau + mod. d'Int PV), rechargé par tes sorts d'abjuration. Copier ces sorts coûte moitié moins."],[6,"Protection projetée","En réaction, ton sceau absorbe les dégâts d'une créature à 9 m."],[10,"Abjuration améliorée","+ bonus de maîtrise aux tests des sorts d'abjuration (contresort, dissipation)."],[14,"Résistance aux sorts","Avantage aux sauvegardes contre les sorts et résistance à leurs dégâts."]],"Divination":[[2,"Présage","Après un repos long, lance deux d20 : tu peux remplacer n'importe quel jet par l'un d'eux. Copier ces sorts coûte moitié moins."],[6,"Divination experte","Un sort de divination de niveau 2+ te rend un emplacement de niveau inférieur."],[10,"Troisième œil","Par une action, un sens spécial jusqu'au repos (vision dans le noir, éthérée, voir l'invisible, lire les langues)."],[14,"Présage supérieur","Trois dés de présage au lieu de deux."]],"Enchantement":[[2,"Regard hypnotique","Par une action, une créature à 1,5 m fait un jet de Sagesse ou est charmée et neutralisée. Copier ces sorts coûte moitié moins."],[6,"Charme instinctif","En réaction, tu détournes une attaque vers une autre créature (jet de Sagesse de l'attaquant)."],[10,"Partage d'enchantement","Un sort d'enchantement à cible unique peut viser une deuxième créature."],[14,"Altération mémorielle","La cible oublie qu'elle a été charmée et une partie de ce qui s'est passé."]],"Illusion":[[2,"Illusion mineure améliorée","Tu connais Illusion mineure et crées à la fois un son et une image. Copier ces sorts coûte moitié moins."],[6,"Illusions malléables","Par une action, tu modifies une illusion durable."],[10,"Double illusoire","En réaction, un double fait rater une attaque contre toi (une fois par repos court)."],[14,"Réalité illusoire","Un objet non magique de ton illusion devient réel pendant 1 minute."]],"Invocation":[[2,"Invocation mineure","Par une action, tu crées un petit objet non magique pour 1 heure. Copier ces sorts coûte moitié moins."],[6,"Permutation","Téléportation de 9 m ou échange de place avec une créature consentante."],[10,"Invocation consciencieuse","Les dégâts ne brisent pas ta concentration sur un sort d'invocation."],[14,"Convocations coriaces","Tes créatures invoquées gagnent 30 PV temporaires."]],"Nécromancie":[[2,"Sinistre moisson","Quand tu tues avec un sort, tu récupères 2 × le niveau du sort en PV (3 × pour la nécromancie). Copier ces sorts coûte moitié moins."],[6,"Serviteurs morts-vivants","Animation des morts crée un mort-vivant de plus, avec plus de PV et de dégâts."],[10,"Insensibilité à la non-vie","Résistance aux dégâts nécrotiques ; tes PV max ne peuvent pas baisser."],[14,"Contrôle des morts-vivants","Par une action, tu prends le contrôle d'un mort-vivant (jet de Charisme)."]],"Transmutation":[[2,"Alchimie mineure","Tu changes temporairement un matériau (bois, pierre, fer, cuivre, argent) en un autre. Copier ces sorts coûte moitié moins."],[6,"Pierre du transmutateur","Une pierre confère un bonus au choix (vision dans le noir, vitesse, maîtrise de la Con, résistance)."],[10,"Métamorphe","Métamorphose sur toi-même sans emplacement (une fois par repos court)."],[14,"Maître transmutateur","Tu détruis la pierre pour un effet majeur (panacée, jouvence, rappel à la vie…)."]]}}};